def test_runtime_theory_trace_consumption_contracts_do_not_claim_alignment() -> None:
    packet_id = "theory_derivation:structured"
    packet = _structured_theory_packet_fixture(packet_id)
    contracts = {
        consumer: runtime_module._runtime_theory_trace_consumption_contract(
            consumer_subsystem=consumer,
            source_theory_packet_id=packet_id,
            theory_packet=packet,
        )
        for consumer in (
            "SimulationEngineer",
            "AlgorithmEngineer",
            "FormalizerProofEngineer",
        )
    }
    artifacts = {
        packet_id: packet,
        "simulation_manifest:structured": {
            "artifact_kind": "RuntimeSimulationManifest",
            "theory_trace_consumption_contract": contracts[
                "SimulationEngineer"
            ],
        },
        "algorithm_sandbox_manifest:structured": {
            "artifact_kind": "RuntimeAlgorithmSandboxManifest",
            "theory_trace_consumption_contract": contracts[
                "AlgorithmEngineer"
            ],
        },
        "formalization_manifest:structured": {
            "artifact_kind": "RuntimeFormalizationManifest",
            "theory_trace_consumption_contract": contracts[
                "FormalizerProofEngineer"
            ],
        },
    }

    evidence_summary = _runtime_evidence_summary(
        [{"blackboard": {"artifacts": artifacts}}]
    )
    theory = evidence_summary["theory"]

    assert theory["all_required_theory_trace_consumers_observed"] is True
    assert theory["structured_theory_trace_consuming_subsystems"] == [
        "AlgorithmEngineer",
        "FormalizerProofEngineer",
        "SimulationEngineer",
    ]
    assert theory["n_theory_trace_consumption_contracts"] == 3
    assert theory["n_theory_trace_alignment_contracts"] == 0
    assert (
        theory["all_required_theory_trace_alignment_consumers_observed"]
        is False
    )
    assert all(
        contract["proof_evidence_status"]
        == "THEORY_TRACE_CONSUMPTION_NOT_PROOF_EVIDENCE"
        for contract in contracts.values()
    )


def test_downstream_manifests_record_runtime_theory_trace_consumption(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    packet_id = "theory_derivation:structured_runtime_handoff"
    packet = _structured_theory_packet_fixture(packet_id)
    packet["estimator_specs"] = [
        {
            "id": "E1",
            "name": "Split conformal interval",
            "algorithm_sketch": (
                "Fit regression on train split, calibrate residual quantile, "
                "and return a prediction interval."
            ),
        }
    ]

    simulation_blackboard = BlackboardState(
        project_id=f"runtime:{question.id}",
        artifacts={packet_id: packet},
    )
    simulation_result = SimulationEvaluatorRuntimeSubsystem().run(
        AgentTask(
            task_id="simulation:structured_runtime_handoff",
            owner_subsystem="SimulationEvaluator",
            objective="Run simulation from structured theory trace.",
            inputs={
                "question": runtime_module._question_to_payload(question),
                "theory_packet_id": packet_id,
                "n_runs": 5,
                "seed": 20260629,
                "architect_context": {},
            },
        ),
        simulation_blackboard,
    )
    simulation_manifest = next(
        artifact
        for artifact in simulation_result.produced_artifacts.values()
        if artifact.get("artifact_kind") == "RuntimeSimulationManifest"
    )

    algorithm_blackboard = BlackboardState(
        project_id=f"runtime:{question.id}",
        artifacts={
            packet_id: packet,
            "simulation_manifest:structured_runtime_handoff": {
                "artifact_kind": "RuntimeSimulationManifest",
                "manifest_id": "simulation_manifest:structured_runtime_handoff",
                "simulation_passed": True,
            },
        },
    )
    algorithm_result = AlgorithmEngineerRuntimeSubsystem(
        out_dir=tmp_path / "algorithm",
        n_runs=5,
        seed=20260629,
        timeout_s=20,
    ).run(
        AgentTask(
            task_id="algorithm:structured_runtime_handoff",
            owner_subsystem="AlgorithmEngineer",
            objective="Run algorithm sandbox from structured theory trace.",
            inputs={
                "question": runtime_module._question_to_payload(question),
                "theory_packet_id": packet_id,
                "simulation_manifest_id": (
                    "simulation_manifest:structured_runtime_handoff"
                ),
                "implementation_gaps": [
                    {
                        "estimator_id": "E1",
                        "status": "REQUIRES_ALGORITHM_ENGINEER_ADAPTER",
                    }
                ],
                "n_runs": 5,
                "seed": 20260629,
                "architect_context": {},
            },
        ),
        algorithm_blackboard,
    )
    algorithm_manifest = next(
        artifact
        for artifact in algorithm_result.produced_artifacts.values()
        if artifact.get("artifact_kind") == "RuntimeAlgorithmSandboxManifest"
    )

    formalization_result = FormalizationEvaluatorRuntimeSubsystem(
        proof_verifier=MockProofVerifier(),
    ).run(
        AgentTask(
            task_id="formalize:structured_runtime_handoff",
            owner_subsystem="FormalizationEvaluator",
            objective="Run formalizer from structured theory trace.",
            inputs={
                "question": runtime_module._question_to_payload(question),
                "theory_packet_id": packet_id,
                "simulation_manifest_id": "simulation_manifest:structured",
                "algorithm_sandbox_manifest_id": "algorithm_sandbox_manifest:structured",
                "architect_context": {},
            },
        ),
        BlackboardState(
            project_id=f"runtime:{question.id}",
            artifacts={
                packet_id: packet,
                "simulation_manifest:structured": simulation_manifest,
                "algorithm_sandbox_manifest:structured": algorithm_manifest,
            },
        ),
    )
    formalization_manifest = next(
        artifact
        for artifact in formalization_result.produced_artifacts.values()
        if artifact.get("artifact_kind") == "RuntimeFormalizationManifest"
    )

    contracts = [
        simulation_manifest["theory_trace_consumption_contract"],
        algorithm_manifest["theory_trace_consumption_contract"],
        formalization_manifest["theory_trace_consumption_contract"],
    ]

    assert [contract["consumer_subsystem"] for contract in contracts] == [
        "SimulationEngineer",
        "AlgorithmEngineer",
        "FormalizerProofEngineer",
    ]
    assert all(
        contract["source_theory_packet_id"] == packet_id
        and contract["theory_derivation_trace_supplied"] is True
        and contract["n_equation_chain_steps_supplied"] == 2
        and contract["n_assumption_ledger_rows_supplied"] == 2
        and contract["has_formalization_handoff"] is True
        for contract in contracts
    )


def test_downstream_routes_missing_theory_context_to_theory_developer(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[0]
    question_payload = runtime_module._question_to_payload(question)

    def blackboard() -> BlackboardState:
        state = BlackboardState(project_id="missing-theory-context-test")
        state.artifacts.update(
            {
                "simulation_manifest:test": {
                    "artifact_kind": "RuntimeSimulationManifest",
                    "manifest_id": "simulation_manifest:test",
                },
                "algorithm_sandbox_manifest:test": {
                    "artifact_kind": "RuntimeAlgorithmSandboxManifest",
                    "manifest_id": "algorithm_sandbox_manifest:test",
                },
            }
        )
        return state

    missing_packet_id = "theory_derivation:missing"
    cases = [
        (
            SimulationEvaluatorRuntimeSubsystem(),
            AgentTask(
                task_id="simulation:conformal_prediction_coverage:missing-id",
                owner_subsystem="SimulationEvaluator",
                objective="Block simulation until a registered theory packet exists.",
                inputs={
                    "question": question_payload,
                    "architect_context": {},
                    "n_runs": 5,
                    "seed": 20260629,
                },
            ),
            True,
        ),
        (
            AlgorithmEngineerRuntimeSubsystem(
                out_dir=tmp_path / "algorithm",
                n_runs=5,
                seed=20260629,
            ),
            AgentTask(
                task_id="algorithm:conformal_prediction_coverage:missing-artifact",
                owner_subsystem="AlgorithmEngineer",
                objective="Block algorithm work until the theory artifact is rehydrated.",
                inputs={
                    "question": question_payload,
                    "theory_packet_id": missing_packet_id,
                    "simulation_manifest_id": "simulation_manifest:test",
                    "implementation_gaps": [{"gap": "needs implementation"}],
                    "architect_context": {},
                },
            ),
            False,
        ),
        (
            FormalizationEvaluatorRuntimeSubsystem(
                proof_verifier=MockProofVerifier(),
            ),
            AgentTask(
                task_id="formalize:conformal_prediction_coverage:missing-artifact",
                owner_subsystem="FormalizationEvaluator",
                objective="Block formalization until the theory artifact is rehydrated.",
                inputs={
                    "question": question_payload,
                    "theory_packet_id": missing_packet_id,
                    "simulation_manifest_id": "simulation_manifest:test",
                    "algorithm_sandbox_manifest_id": (
                        "algorithm_sandbox_manifest:test"
                    ),
                    "architect_context": {},
                },
            ),
            False,
        ),
    ]

    for subsystem, task, missing_packet_id_expected in cases:
        result = subsystem.run(task, blackboard())

        assert result.status == "REVISE"
        assert result.next_task is not None
        assert result.next_task.owner_subsystem == "TheoryDeveloper"
        assert result.failure_classification == (
            "runtime_theory_derivation_trace_incomplete"
        )
        assert not result.tool_calls
        feedback = result.next_task.inputs["environment_feedback"]
        assert feedback["trigger"] == "RUNTIME_THEORY_DERIVATION_TRACE_INCOMPLETE"
        assert "missing_theory_derivation_packet" in feedback[
            "failure_classifications"
        ]
        if missing_packet_id_expected:
            assert "missing_theory_packet_id" in feedback[
                "failure_classifications"
            ]
            assert feedback["source_theory_packet_id"] == ""
        else:
            assert feedback["source_theory_packet_id"] == missing_packet_id
        assert result.next_task.expected_artifacts == ("theory_derivation_packet",)


def test_theory_developer_validation_failure_routes_compact_retry() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[0]
    question_payload = runtime_module._question_to_payload(question)

    class RejectingTheoryDeveloper:
        def derive(self, *_args: object, **_kwargs: object) -> dict[str, object]:
            raise PacketValidationError(
                validation_label="LLM TheoryDeveloper packet",
                attempts=3,
                errors=["JSONDecodeError: response ended inside formalization_requests"],
                history=[
                    {
                        "attempt_index": 2,
                        "provider": "anthropic",
                        "model": "claude-sonnet-4-6",
                        "ok": False,
                        "errors": [
                            "JSONDecodeError: response ended inside formalization_requests"
                        ],
                        "request_max_tokens": 2500,
                        "response_metadata": {
                            "provider_stop_reason": "max_tokens",
                            "provider_usage": {"output_tokens": 2500},
                        },
                    }
                ],
            )

    subsystem = TheoryDeveloperRuntimeSubsystem(
        theory_developer=RejectingTheoryDeveloper(),  # type: ignore[arg-type]
        n_runs=5,
        seed=20260629,
    )
    task = AgentTask(
        task_id="theory-resume-refresh:conformal_prediction_coverage:test",
        owner_subsystem="TheoryDeveloper",
        objective="Produce a structured theory packet.",
        inputs={
            "question": question_payload,
            "architect_context": {
                "runtime_requested_evidence_contract": {
                    "formal_verification_policy": "optional"
                }
            },
        },
        allowed_tools=("model_backend", "rag_memory"),
        expected_artifacts=("theory_derivation_packet",),
    )

    result = subsystem.run(task, BlackboardState(project_id="theory-validation-test"))

    assert result.status == "REVISE"
    assert result.failure_classification == "theory_developer_packet_truncated_json"
    assert result.next_task is not None
    assert result.next_task.owner_subsystem == "TheoryDeveloper"
    assert result.next_task.inputs["theory_developer_validation_retry_attempt"] == 1
    retry_feedback = result.next_task.inputs["environment_feedback"]
    assert retry_feedback["failure_classification"] == (
        "theory_developer_packet_truncated_json"
    )
    assert retry_feedback["truncation_detected"] is True
    assert "minimum row counts" in retry_feedback["required_revision"]
    assert result.produced_artifacts
    failure_artifact = next(iter(result.produced_artifacts.values()))
    assert failure_artifact["artifact_kind"] == (
        "RuntimeTheoryDeveloperValidationFailure"
    )
    assert failure_artifact["learning_rows"][0]["proof_evidence_status"] == (
        "THEORY_DEVELOPER_PACKET_VALIDATION_FAILURE_NOT_PROOF_EVIDENCE"
    )
    assert result.observations[0].payload["truncation_detected"] is True


