def test_runtime_routes_missing_explicit_handoff_artifacts_to_producers(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[0]
    question_payload = runtime_module._question_to_payload(question)
    theory_packet_id = "theory_derivation:handoff_structured"
    simulation_manifest_id = "simulation_manifest:handoff"
    algorithm_manifest_id = "algorithm_sandbox_manifest:handoff"
    formalization_manifest_id = "formalization_manifest:handoff"
    theory_packet = _structured_theory_packet_fixture(theory_packet_id)

    cases = [
        (
            AlgorithmEngineerRuntimeSubsystem(
                out_dir=tmp_path / "algorithm",
                n_runs=5,
                seed=20260629,
            ),
            BlackboardState(
                project_id="missing-simulation-handoff",
                artifacts={theory_packet_id: theory_packet},
            ),
            AgentTask(
                task_id="algorithm:missing-simulation-handoff",
                owner_subsystem="AlgorithmEngineer",
                objective="Require an explicit simulation handoff artifact.",
                inputs={
                    "question": question_payload,
                    "theory_packet_id": theory_packet_id,
                    "simulation_manifest_id": simulation_manifest_id,
                    "implementation_gaps": [{"gap": "needs algorithm sandbox"}],
                    "architect_context": {},
                },
            ),
            "SimulationEvaluator",
            simulation_manifest_id,
            "simulation_manifest",
        ),
        (
            FormalizationEvaluatorRuntimeSubsystem(
                proof_verifier=MockProofVerifier(),
            ),
            BlackboardState(
                project_id="missing-algorithm-handoff",
                artifacts={
                    theory_packet_id: theory_packet,
                    simulation_manifest_id: {
                        "artifact_kind": "RuntimeSimulationManifest",
                        "manifest_id": simulation_manifest_id,
                    },
                },
            ),
            AgentTask(
                task_id="formalize:missing-algorithm-handoff",
                owner_subsystem="FormalizationEvaluator",
                objective="Require an explicit algorithm handoff artifact.",
                inputs={
                    "question": question_payload,
                    "theory_packet_id": theory_packet_id,
                    "simulation_manifest_id": simulation_manifest_id,
                    "algorithm_sandbox_manifest_id": algorithm_manifest_id,
                    "architect_context": {},
                },
            ),
            "AlgorithmEngineer",
            algorithm_manifest_id,
            "algorithm_sandbox_manifest",
        ),
        (
            runtime_module.CriticEvaluatorRuntimeSubsystem(),
            BlackboardState(
                project_id="missing-formalization-handoff",
                artifacts={
                    theory_packet_id: theory_packet,
                    simulation_manifest_id: {
                        "artifact_kind": "RuntimeSimulationManifest",
                        "manifest_id": simulation_manifest_id,
                    },
                    algorithm_manifest_id: {
                        "artifact_kind": "RuntimeAlgorithmSandboxManifest",
                        "manifest_id": algorithm_manifest_id,
                    },
                },
            ),
            AgentTask(
                task_id="critic:missing-formalization-handoff",
                owner_subsystem="CriticEvaluator",
                objective="Require an explicit formalization handoff artifact.",
                inputs={
                    "question": question_payload,
                    "theory_packet_id": theory_packet_id,
                    "simulation_manifest_id": simulation_manifest_id,
                    "algorithm_sandbox_manifest_id": algorithm_manifest_id,
                    "formalization_manifest_id": formalization_manifest_id,
                    "architect_context": {},
                },
            ),
            "FormalizationEvaluator",
            formalization_manifest_id,
            "formalization_manifest",
        ),
    ]

    for (
        subsystem,
        blackboard,
        task,
        expected_owner,
        missing_artifact_id,
        missing_role,
    ) in cases:
        result = subsystem.run(task, blackboard)

        assert result.status == "REVISE"
        assert result.failure_classification == "runtime_handoff_artifact_missing"
        assert result.next_task is not None
        assert result.next_task.owner_subsystem == expected_owner
        assert not result.produced_artifacts
        assert not result.tool_calls
        feedback = result.next_task.inputs["environment_feedback"]
        assert feedback["trigger"] == "RUNTIME_HANDOFF_ARTIFACT_MISSING"
        assert feedback["missing_artifact_id"] == missing_artifact_id
        assert feedback["missing_artifact_role"] == missing_role
        assert f"missing_{missing_role}" in feedback["failure_classifications"]
        assert feedback["repair_owner_agent"] == expected_owner
        assert feedback["proof_evidence_status"] == (
            "HANDOFF_ARTIFACT_MISSING_FEEDBACK_NOT_PROOF_EVIDENCE"
        )


def test_runtime_manifest_exports_missing_handoff_feedback_memory(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[0]
    theory_packet_id = "theory_derivation:runtime_handoff_structured"
    missing_simulation_manifest_id = "simulation_manifest:runtime_missing"
    theory_developer = LLMTheoryDeveloperAgent(
        provider=StaticArchitectLLMProvider(_runtime_sample_response()),
        config=ResearchArchitectConfig(
            provider_name="static",
            model="static-theory-model",
        ),
    )
    task = AgentTask(
        task_id="algorithm:runtime-missing-simulation-handoff",
        owner_subsystem="AlgorithmEngineer",
        objective="Recover missing simulation handoff before algorithm work.",
        inputs={
            "question": runtime_module._question_to_payload(question),
            "theory_packet_id": theory_packet_id,
            "simulation_manifest_id": missing_simulation_manifest_id,
            "implementation_gaps": [{"gap": "requires algorithm sandbox"}],
            "architect_context": {},
        },
    )

    manifest = run_research_agent_runtime(
        [question],
        tmp_path / "runtime",
        theory_developer=theory_developer,
        config=ResearchAgentRuntimeConfig(max_iterations=1),
        initial_task_overrides={question.id: task},
        initial_blackboard_artifacts={
            question.id: {
                theory_packet_id: _structured_theory_packet_fixture(
                    theory_packet_id
                )
            }
        },
    )

    assert manifest["status_counts"] == {"MAX_ITERATIONS_REACHED": 1}
    assert manifest["terminal_subsystem"] == "AlgorithmEngineer"
    assert manifest["n_runtime_handoff_artifact_feedback_learning_rows"] == 1
    assert manifest["n_runtime_handoff_artifact_feedback_next_action_rows"] == 1

    result_path = Path(manifest["artifacts"]["per_question_results"][0])
    result = json.loads(result_path.read_text(encoding="utf-8"))
    assert result["traces"][0]["failure_classification"] == (
        "runtime_handoff_artifact_missing"
    )
    assert result["traces"][0]["next_task"]["owner_subsystem"] == (
        "SimulationEvaluator"
    )

    learning_rows = [
        json.loads(line)
        for line in Path(
            manifest["artifacts"]["runtime_learning_rows_jsonl"]
        ).read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    handoff_rows = [
        row
        for row in learning_rows
        if row.get("learning_task") == (
            "runtime_handoff_artifact_missing_feedback"
        )
    ]
    assert len(handoff_rows) == 1
    assert handoff_rows[0]["next_owner_subsystem"] == "SimulationEvaluator"
    assert handoff_rows[0]["missing_artifact_id"] == missing_simulation_manifest_id
    assert handoff_rows[0]["input_summary"]["trigger"] == (
        "RUNTIME_HANDOFF_ARTIFACT_MISSING"
    )

    agenda_rows = [
        json.loads(line)
        for line in Path(
            manifest["artifacts"]["runtime_next_action_agenda_jsonl"]
        ).read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    handoff_agenda_rows = [
        row
        for row in agenda_rows
        if row.get("trigger") == "RUNTIME_HANDOFF_ARTIFACT_MISSING"
    ]
    assert len(handoff_agenda_rows) == 1
    assert handoff_agenda_rows[0]["owner_subsystem"] == "SimulationEvaluator"
    assert handoff_agenda_rows[0]["missing_artifact_id"] == (
        missing_simulation_manifest_id
    )

    pending_task_path = Path(manifest["artifacts"]["runtime_pending_next_task_json"])
    pending_payload = json.loads(pending_task_path.read_text(encoding="utf-8"))
    pending_memory = pending_payload["pending_next_task"]["inputs"][
        "architect_context"
    ]["runtime_learning_memory"]
    assert any(
        row.get("learning_task") == "runtime_handoff_artifact_missing_feedback"
        and row.get("missing_artifact_id") == missing_simulation_manifest_id
        for row in pending_memory["rows"]
    )

    audit = audit_research_agent_runtime(tmp_path / "runtime")
    assert audit["n_runtime_handoff_artifact_missing_feedback_rows"] == 1
    assert audit["n_runtime_handoff_artifact_missing_learning_rows"] == 1
    assert audit["n_runtime_handoff_artifact_missing_agenda_rows"] == 1
    assert audit["runtime_handoff_artifact_missing_ids"] == [
        missing_simulation_manifest_id
    ]
    scorecard_rows = {
        row["requirement_id"]: row for row in audit["capability_scorecard"]["rows"]
    }
    handoff_score = scorecard_rows["explicit_handoff_artifacts_available"]
    assert handoff_score["passed"] is False
    assert missing_simulation_manifest_id in handoff_score["evidence"]
    assert any(
        "explicit subsystem handoff artifact ids were missing" in gap
        for gap in audit["capability_gaps"]
    )


