def test_research_acceptance_contract_respects_formal_policy() -> None:
    manifest = {
        "runtime_completion_summary": {
            "accepted": 1,
        },
        "runtime_evidence_truth_table": {
            "source_theorem_kernel_verified": False,
            "formal_gaps_open": True,
        },
        "n_kernel_verified_subclaims": 0,
        "n_formal_gaps": 2,
    }

    required = _runtime_research_acceptance_contract_from_manifest(
        manifest,
        formal_verification_policy="required",
    )
    advisory = _runtime_research_acceptance_contract_from_manifest(
        manifest,
        formal_verification_policy="advisory",
    )
    optional_simulation_first = _runtime_research_acceptance_contract_from_manifest(
        manifest,
        formal_verification_policy="optional",
        recommended_research_path="simulation_first",
    )

    assert required["formal_required_for_final"] is True
    assert required["research_acceptance_status"] == (
        "FORMAL_REQUIRED_BLOCKED_AFTER_RUNTIME_ACCEPTED"
    )
    assert required["can_report_research_candidate"] is False
    assert required["formally_verified_level"] == "none"
    assert advisory["formal_required_for_final"] is False
    assert advisory["research_acceptance_status"] == (
        "RESEARCH_CANDIDATE_ACCEPTED_FORMAL_ADVISORY"
    )
    assert advisory["can_report_research_candidate"] is True
    assert advisory["must_disclose_formal_gaps"] is True
    assert optional_simulation_first["formal_required_for_final"] is False
    assert optional_simulation_first["recommended_research_path"] == "simulation_first"
    assert optional_simulation_first["research_acceptance_status"] == (
        "RESEARCH_CANDIDATE_ACCEPTED_WITH_FORMAL_GAPS_DISCLOSED"
    )
    assert _normalized_formal_verification_policy("OPTIONAL") == "optional"
    with pytest.raises(ValueError):
        _normalized_formal_verification_policy("always")


def test_optional_formal_policy_follows_architect_recommendation() -> None:
    results = [
        {
            "blackboard": {
                "artifacts": {
                    "architect:test": {
                        "packet_id": "architect:test",
                        "evidence_contract": {
                            "formal_verification_policy": "required",
                            "recommended_research_path": "proof_first",
                            "formal_required_for_final": True,
                        },
                    }
                }
            },
            "traces": [],
        }
    ]

    architect_policy = _runtime_architect_recommended_formal_verification_policy(
        results
    )
    architect_path = _runtime_architect_recommended_research_path(results)

    assert architect_policy == "required"
    assert architect_path == "proof_first"
    assert (
        _effective_formal_verification_policy(
            requested_policy="optional",
            architect_recommended_policy=architect_policy,
        )
        == "required"
    )
    assert (
        _effective_formal_verification_policy(
            requested_policy="advisory",
            architect_recommended_policy=architect_policy,
        )
        == "advisory"
    )
    assert (
        _effective_recommended_research_path(
            effective_formal_verification_policy="required",
            architect_recommended_path=architect_path,
        )
        == "proof_first"
    )
    assert (
        _effective_recommended_research_path(
            effective_formal_verification_policy="advisory",
            architect_recommended_path="",
        )
        == "simulation_first"
    )
    assert (
        _effective_recommended_research_path(
            effective_formal_verification_policy="advisory",
            requested_recommended_path="dual_track",
            architect_recommended_path="proof_first",
        )
        == "dual_track"
    )


