def test_research_path_execution_summary_scopes_to_current_trace_artifacts() -> None:
    results = [
        {
            "blackboard": {
                "artifacts": {
                    "retrieval:historical": {
                        "artifact_kind": "RuntimeRetrievalMemoryManifest",
                        "runtime_architect_control": {
                            "subsystem": "RetrievalMemory",
                            "formal_verification_policy": "optional",
                            "recommended_research_path": "dual_track",
                            "formal_required_for_final": False,
                            "evidence_contract": {
                                "formal_verification_policy": "optional",
                                "recommended_research_path": "dual_track",
                                "formal_required_for_final": False,
                            },
                        },
                    },
                    "formalization:current": {
                        "artifact_kind": "RuntimeFormalizationManifest",
                        "runtime_architect_control": {
                            "subsystem": "ProofEngineer",
                            "formal_verification_policy": "required",
                            "recommended_research_path": "dual_track",
                            "formal_required_for_final": True,
                            "evidence_contract": {
                                "formal_verification_policy": "required",
                                "recommended_research_path": "dual_track",
                                "formal_required_for_final": True,
                            },
                        },
                    },
                }
            },
            "traces": [
                {
                    "subsystem": "ProofEngineer",
                    "produced_artifact_ids": ["formalization:current"],
                }
            ],
        }
    ]

    summary = _runtime_research_path_execution_summary(
        results,
        effective_formal_verification_policy="required",
        effective_recommended_research_path="dual_track",
    )

    assert summary["path_control_propagated"] is True
    assert summary["n_current_artifacts"] == 1
    assert summary["n_current_artifacts_missing_architect_control"] == 0
    assert summary["n_produced_artifact_ids_missing_from_blackboard"] == 0
    assert summary["n_controlled_artifacts"] == 1
    assert summary["n_historical_controlled_input_artifacts_skipped"] == 1
    assert summary["n_policy_mismatches"] == 0
    assert summary["n_path_mismatches"] == 0
    assert summary["controlled_subsystems"] == ["ProofEngineer"]


def test_simulation_engineer_prompt_compacts_theory_context() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    prompt = build_simulation_engineer_prompt(
        question=question,
        theory_packet={
            "packet_id": "theory:test",
            "problem_card": {
                "estimand": "coverage",
                "assumptions": ["exchangeability", "x" * 5000],
                "desired_theorem_type": "finite-sample coverage",
                "irrelevant_long_field": "x" * 5000,
            },
            "estimator_specs": [
                {"id": "E1", "name": "split conformal", "algorithm_sketch": "calibrate residuals"},
                {"id": "E2", "name": "extra", "algorithm_sketch": "unused"},
                {"id": "E3", "name": "dropped", "algorithm_sketch": "unused"},
            ],
            "theorem_cards": [
                {
                    "id": "T1",
                    "conclusion": "coverage",
                    "semantic_risks": ["exchangeability semantics"],
                    "long_proof_strategy": "y" * 5000,
                }
            ],
            "simulation_ademp_spec": {
                "aim": "stress coverage",
                "dgps": ["nonlinear", "x" * 5000],
                "methods": ["split conformal", "x" * 5000],
            },
            "theory_derivation_packet": {
                "derivation_summary": "derive finite-sample coverage from exchangeability",
                "derivation_steps": [
                    {
                        "id": "exchangeable_scores",
                        "claim": "Calibration and test scores are exchangeable.",
                        "equation_or_argument": "rank(score_test) is uniform among calibration ranks",
                        "depends_on": [],
                        "formal_goal": "coverage_theorem",
                        "risk": "exchangeability must match simulation split",
                    }
                ],
                "equation_chain": [
                    {
                        "step_id": "coverage_identity",
                        "lhs": "P(Y_test in C(X_test))",
                        "relation": ">=",
                        "rhs": "1-alpha",
                        "justification": "exchangeable rank argument",
                        "depends_on": ["exchangeable_scores"],
                    }
                ],
                "assumption_ledger": [
                    {
                        "assumption": "exchangeability",
                        "role": "simulation",
                        "used_in": ["exchangeable_scores", "coverage_identity"],
                        "risk_if_dropped": "coverage simulation no longer targets theorem",
                    }
                ],
                "formalization_handoff": {
                    "source_theorem_target": "coverage_theorem",
                    "semantic_alignment_constraints": ["preserve split exchangeability"],
                },
            },
        },
        registered_problem={"problem_class": "distribution_free_conformal_prediction"},
        registered_procedures=[],
        n_runs=20,
        seed=7,
        environment_feedback={
            "architect_evidence_contract": {
                "formal_verification_policy": "advisory",
                "recommended_research_path": "simulation_first",
                "formal_required_for_final": False,
                "simulation_targets": ["finite-n misspecification stress"],
                "disclosure_requirements": ["not formally verified"],
            },
            "architect_subsystem_acceptance_gate": "stress DGPs before proof work",
        },
    )

    assert "x" * 5000 not in prompt
    assert "y" * 5000 not in prompt
    assert '"E1"' in prompt
    assert '"E3"' not in prompt
    assert "Return ONLY one compact JSON object" in prompt
    assert '"dgp_plan"' not in prompt
    assert '"failure_interpretation"' not in prompt
    assert '"recommended_research_path":"simulation_first"' in prompt
    assert "finite-n misspecification stress" in prompt
    assert "stress DGPs before proof work" in prompt
    assert "theory_derivation_trace" in prompt
    assert "coverage_identity" in prompt
    assert "exchangeability must match simulation split" in prompt
    assert "preserve split exchangeability" in prompt
    assert "align DGPs, estimands, metrics, and stress tests" in prompt


