def test_algorithm_engineer_prompt_compacts_theory_and_simulation_context() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    long_text = "long_algorithm_context_" + ("z" * 5000)
    prompt = build_algorithm_engineer_prompt(
        question=question,
        theory_packet={
            "packet_id": "theory:test",
            "problem_card": {
                "estimand": "coverage",
                "assumptions": ["exchangeability", long_text],
                "desired_theorem_type": "finite-sample coverage",
                "unused_large_field": long_text,
            },
            "estimator_specs": [
                {"id": "E1", "name": "split conformal interval", "algorithm_sketch": long_text},
                {"id": "E2", "name": "extra", "algorithm_sketch": "unused"},
                {"id": "E3", "name": "dropped", "algorithm_sketch": "unused"},
            ],
            "theorem_cards": [
                {"id": "T1", "conclusion": long_text, "semantic_risks": [long_text]},
            ],
            "simulation_ademp_spec": {
                "methods": [long_text for _ in range(5)],
                "performance_measures": [long_text for _ in range(5)],
                "stress_tests": [long_text for _ in range(5)],
            },
            "theory_derivation_packet": {
                "derivation_summary": "map split-conformal interval code to coverage score ranks",
                "derivation_steps": [
                    {
                        "id": "calibrate_quantile",
                        "claim": "The implementation must compute a calibration residual quantile.",
                        "equation_or_argument": "q_hat = empirical quantile of calibration residuals",
                        "depends_on": [],
                        "formal_goal": "coverage_theorem",
                        "risk": "off-by-one quantile changes coverage",
                    }
                ],
                "equation_chain": [
                    {
                        "step_id": "interval_width",
                        "lhs": "C_hat(x)",
                        "relation": "=",
                        "rhs": "[m_hat(x)-q_hat, m_hat(x)+q_hat]",
                        "justification": "split conformal interval construction",
                        "depends_on": ["calibrate_quantile"],
                    }
                ],
                "assumption_ledger": [
                    {
                        "assumption": "exchangeability",
                        "role": "algorithmic",
                        "used_in": ["calibrate_quantile", "interval_width"],
                        "risk_if_dropped": "runtime coverage metric targets the wrong claim",
                    }
                ],
                "formalization_handoff": {
                    "source_theorem_target": "coverage_theorem",
                    "semantic_alignment_constraints": ["keep rank quantile semantics"],
                },
            },
        },
        simulation_manifest={
            "manifest_id": "simulation:test",
            "simulation_passed": True,
            "registered_procedures": [
                {"procedure_id": "split_conformal_interval", "registered_simulator": long_text}
            ],
            "simulations": [
                {"procedure_id": "E1", "passed": True, "metrics": {"coverage": long_text}},
                {"procedure_id": "E2", "passed": True, "metrics": {"unused": long_text}},
                {"procedure_id": "E3", "passed": True, "metrics": {"dropped": long_text}},
            ],
            "implementation_gaps": [{"estimator_id": "E1", "status": "gap", "reason": long_text}],
            "raw_large_trace": long_text,
        },
        implementation_gaps=[{"estimator_id": "E1", "status": "gap", "reason": long_text}],
        environment_feedback={
            "architect_evidence_contract": {
                "formal_verification_policy": "advisory",
                "recommended_research_path": "simulation_first",
                "formal_required_for_final": False,
                "simulation_targets": ["runtime benchmark"],
            },
            "architect_subsystem_acceptance_gate": "prefer registered implementation template",
        },
    )

    assert "z" * 5000 not in prompt
    assert "raw_large_trace" not in prompt
    assert '"E1"' in prompt
    assert '"E3"' not in prompt
    assert "Return ONLY one compact JSON object" in prompt
    assert "leave sandbox_code_drafts empty whenever a template matches" in prompt
    assert '"code_generation_plan"' not in prompt
    assert '"promotion_gate"' not in prompt
    assert len(prompt) < 22000
    assert '"recommended_research_path":"simulation_first"' in prompt
    assert "prefer registered implementation template" in prompt
    assert "theory_derivation_trace" in prompt
    assert "interval_width" in prompt
    assert "off-by-one quantile changes coverage" in prompt
    assert "keep rank quantile semantics" in prompt
    assert "align generated code, validation metrics" in prompt


