def test_algorithm_engineer_normalizes_sandbox_draft_metadata() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    packet = _normalize_algorithm_packet(
        {
            "theory_trace_alignment": _structured_theory_trace_alignment_fixture(),
            "implementation_targets": [
                {
                    "estimator_id": "E1",
                    "registered_template_hint": "none",
                }
            ],
            "sandbox_code_drafts": [
                {
                    "language": "python3",
                    "entrypoint": "run_sandbox(seed: int, replicates: int) -> dict",
                    "code": "def run_sandbox(seed, replicates):\n    return {'empirical_coverage': 1.0, 'target_coverage': 0.95}\n",
                }
            ],
            "next_actions": [{"owner": "AlgorithmEngineer", "action": "execute"}],
        },
        question=question,
        model="claude-haiku-4-5-20251001",
        model_tier="haiku",
        provider_name="anthropic",
        backend_provider_name="anthropic",
        raw_response="{}",
        theory_packet=_structured_theory_packet_fixture(),
        implementation_gaps=[
            {
                "estimator_id": "E1",
                "status": "REQUIRES_ALGORITHM_ENGINEER_ADAPTER",
            }
        ],
    )

    draft = packet["sandbox_code_drafts"][0]
    assert draft["language"] == "python"
    assert draft["entrypoint"] == "run_sandbox"
    assert draft["estimator_id"] == "E1"
    assert packet["backend_provider"] == "anthropic"
    contract = packet["theory_trace_consumption_contract"]
    assert contract["consumer_subsystem"] == "AlgorithmEngineer"
    assert contract["theory_derivation_trace_supplied"] is True
    assert contract["n_equation_chain_steps_supplied"] == 2
    alignment = packet["theory_trace_alignment_contract"]
    assert alignment["consumer_subsystem"] == "AlgorithmEngineer"
    assert alignment["structured_alignment_observed"] is True
    assert alignment["supported_assumptions"] == ["positivity"]
    assert validate_algorithm_engineer_packet(packet) == []
    assert (
        _validate_capability_eval_generated_algorithm_packet(
            packet,
            implementation_gaps=[
                {
                    "estimator_id": "E1",
                    "status": "REQUIRES_ALGORITHM_ENGINEER_ADAPTER",
                }
            ],
        )
        == []
    )


