def test_critic_evaluator_prompt_compacts_trace_context() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    long_text = "long_critic_context_" + ("q" * 5000)
    prompt = build_critic_evaluator_prompt(
        question=question,
        retrieval_manifest={"manifest_id": "retrieval:test", "boundary": long_text},
        theory_packet={"packet_id": "theory:test", "unused_large_field": long_text},
        simulation_manifest={"manifest_id": "simulation:test", "simulation_passed": True},
        algorithm_manifest={"manifest_id": "algorithm:test", "n_executed": 1, "n_passed": 1},
        formalization_manifest={
            "manifest_id": "formalization:test",
            "counts": {"kernel_verified": 0, "formal_gap": 1},
            "proof_evidence_status": "FORMAL_GAPS_REMAIN",
            "runtime_architect_control": {
                "evidence_contract": {
                    "formal_verification_policy": "required",
                    "recommended_research_path": "proof_first",
                    "formal_required_for_final": True,
                },
                "acceptance_gate": "source theorem kernel proof required",
            },
            "huge_trace": long_text,
        },
        deterministic_agenda=[
            {
                "id": f"agenda_{idx}",
                "owner_subsystem": "TheoryDeveloper",
                "trigger": long_text,
                "action": long_text,
                "acceptance_gate": long_text,
                "priority": "high",
                "unused_large_field": long_text,
            }
            for idx in range(8)
        ],
        deterministic_learning_rows=[
            {
                "learning_task": "source_to_bridge_premise_derivation_feedback",
                "input_signal": "{ω | rank ω ∈ BadRanks}ᶜ ⊆ covered",
                "target_behavior": "route semantic premise repair upstream",
            },
            {
                "learning_task": "source_to_bridge_premise_semantic_repair_feedback",
                "target_theorem_name": "split_conformal_coverage",
                "premise_name": "hRank",
                "premise_target_status": "ADAPTER_PREMISE_TARGET_EXTRACTED",
                "premise_target_type": (
                    "∀ r ∈ BadRanks, P {ω | rank ω = r} ≤ α r"
                ),
                "premise_derivation_gap_kind": (
                    "concrete_premise_target_lacks_nonvacuous_derivation_candidate"
                ),
                "input_summary": {
                    "trigger": "SOURCE_TO_BRIDGE_PREMISE_DERIVATION_GAP",
                    "premise_name": "hRank",
                    "premise_target_type": (
                        "∀ r ∈ BadRanks, P {ω | rank ω = r} ≤ α r"
                    ),
                },
                "target_behavior": "route semantic premise repair upstream",
            },
            {
                "learning_task": "source_theorem_truth_table_feedback",
                "target_theorem_name": "split_conformal_coverage",
                "input_summary": {
                    "trigger": "RUNTIME_EVIDENCE_TRUTH_TABLE",
                    "source_theorem_kernel_verified": False,
                    "proof_body_goal_reached": True,
                    "failure_classification": (
                        "proof_body_verified_adapter_context_insufficient"
                    ),
                },
                "target_behavior": "route exact source theorem blocker",
            },
        ]
        + [
            {
                "learning_task": f"learn_{idx}",
                "input_signal": long_text,
                "target_behavior": long_text,
                "unused_large_field": long_text,
            }
            for idx in range(8)
        ],
    )

    assert "q" * 5000 not in prompt
    assert "unused_large_field" not in prompt
    assert '"agenda_0"' in prompt
    assert '"agenda_4"' not in prompt
    assert "{ω | rank ω ∈ BadRanks}ᶜ ⊆ covered" in prompt
    assert "source_to_bridge_premise_semantic_repair_feedback" in prompt
    assert "hRank" in prompt
    assert "∀ r ∈ BadRanks, P {ω | rank ω = r} ≤ α r" in prompt
    assert "SOURCE_TO_BRIDGE_PREMISE_DERIVATION_GAP" in prompt
    assert "source_theorem_truth_table_feedback" in prompt
    assert "RUNTIME_EVIDENCE_TRUTH_TABLE" in prompt
    assert "source_theorem_kernel_verified=false" in prompt
    assert "Do not summarize that state as accepted theorem proof" in prompt
    assert "Include only required fields" in prompt
    assert '"learning_updates"' not in prompt
    assert '"recommended_research_path":"proof_first"' in prompt
    assert "source theorem kernel proof required" in prompt
    assert '"benchmark_expansion_plan"' not in prompt
    assert len(prompt) < 18000


def test_runtime_failure_summary_surfaces_failed_subsystem() -> None:
    completion = _runtime_completion_summary(
        [
            {
                "status": "FAILED",
                "final_task_id": "algorithm:q1:abc",
                "traces": [
                    {
                        "task": {
                            "task_id": "algorithm:q1:abc",
                            "inputs": {
                                "question": {"id": "q1", "title": "Question 1"},
                            },
                        },
                        "subsystem": "AlgorithmEngineer",
                        "status": "FAILED",
                        "failure_classification": "subsystem_exception",
                        "next_task_id": "",
                    }
                ],
            }
        ]
    )
    summary = _runtime_failure_summary(completion)

    assert summary["has_failure"] is True
    assert summary["failed_question_id"] == "q1"
    assert summary["failed_subsystem"] == "AlgorithmEngineer"
    assert summary["failed_task_id"] == "algorithm:q1:abc"
    assert summary["failure_classification"] == "subsystem_exception"


def test_runtime_failure_summary_does_not_label_budget_pending_as_failure() -> None:
    completion = _runtime_completion_summary(
        [
            {
                "status": "MAX_ITERATIONS_REACHED",
                "final_task_id": "theory-critic-revise:q1:abc",
                "traces": [
                    {
                        "task": {
                            "task_id": "critic:q1:abc",
                            "inputs": {
                                "question": {"id": "q1", "title": "Question 1"},
                            },
                        },
                        "subsystem": "CriticEvaluator",
                        "status": "REVISE",
                        "failure_classification": "critic_requested_theory_revision",
                        "next_task_id": "theory-critic-revise:q1:abc",
                        "next_task": {
                            "task_id": "theory-critic-revise:q1:abc",
                            "owner_subsystem": "TheoryDeveloper",
                            "objective": "Revise the theory packet from critic feedback.",
                            "inputs": {
                                "question": {"id": "q1", "title": "Question 1"},
                                "environment_feedback": {
                                    "failure_classification": (
                                        "critic_requested_theory_revision"
                                    ),
                                    "required_repair": "address formal gap",
                                },
                            },
                            "allowed_tools": ["model_backend", "rag_memory"],
                            "budget": {},
                            "expected_artifacts": [
                                "critic_revised_theory_derivation_packet"
                            ],
                            "acceptance_gate": "revised packet addresses critic feedback",
                            "stop_condition": "reroute through gates",
                        },
                    }
                ],
            }
        ]
    )
    summary = _runtime_failure_summary(completion)

    assert summary["has_failure"] is False
    assert summary["has_incomplete_pending_work"] is True
    assert summary["failed_subsystem"] == ""
    assert summary["terminal_subsystem"] == "CriticEvaluator"
    assert summary["terminal_kind"] == "budget_exhausted_with_pending_next_task"
    assert summary["pending_next_task_id"] == "theory-critic-revise:q1:abc"
    assert summary["pending_next_task"]["owner_subsystem"] == "TheoryDeveloper"
    assert (
        summary["pending_next_task"]["inputs"]["environment_feedback"][
            "required_repair"
        ]
        == "address formal gap"
    )


def test_formalization_validator_failure_exports_learning_row() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    question_payload = {
        "id": question.id,
        "title": question.title,
        "description": question.description,
        "tags": list(question.tags),
    }

    class RejectingFormalizer:
        def propose(self, **_kwargs: object) -> dict[str, object]:
            raise PacketValidationError(
                validation_label="LLM Formalizer/ProofEngineer packet",
                attempts=2,
                errors=[
                    (
                        "source_to_bridge_premise_derivation_candidates Lean "
                        "candidate missing required semantic anchor references: "
                        "conformal_rank, conformal_covered, conformal_α_total"
                    ),
                    (
                        "source_to_bridge_premise_derivation_candidates Lean "
                        "candidate takes adapter objects as theorem binders instead "
                        "of deriving them from source binders: conformal_rank, "
                        "conformal_bad_ranks"
                    ),
                    (
                        "source_to_bridge_premise_derivation_candidates entry "
                        "missing source-binding contract metadata; include a "
                        "source_to_bridge_premise_derivation_candidate_request_id/"
                        "object, a source_to_bridge_grouped_premise_derivation_"
                        "candidate_request_id/object, or explicit required_semantic_"
                        "anchor_reference_names and adapter_object_names_requiring_"
                        "source_instantiation from the runtime memory request"
                    ),
                    (
                        "capability_eval formal target "
                        "split_conformal_finite_sample_coverage_v10 Lean sketch "
                        "contains unsupported contradiction proof shortcut absurd"
                    ),
                    (
                        "capability_eval formal target "
                        "split_conformal_finite_sample_coverage_v10 must set "
                        "expected_status=NEEDS_KERNEL_CHECK"
                    ),
                    (
                        "capability_eval formal target "
                        "split_conformal_finite_sample_coverage_source_theorem "
                        "must contain a Lean theorem or lemma declaration"
                    ),
                ],
                history=[
                    {
                        "attempt_index": 1,
                        "provider": "anthropic",
                        "model": "claude-sonnet-4-6",
                        "raw_response_fingerprint": "abc123",
                    }
                ],
            )

    subsystem = FormalizationEvaluatorRuntimeSubsystem(
        proposal_agent=RejectingFormalizer(),
        proof_verifier=MockProofVerifier(),
        max_proof_obligations=1,
    )
    blackboard = BlackboardState(
        project_id="test",
        artifacts={
            "theory_packet:test": _runtime_sample_response(),
            "simulation_manifest:test": {"manifest_id": "simulation_manifest:test"},
            "algorithm_sandbox_manifest:test": {
                "manifest_id": "algorithm_sandbox_manifest:test"
            },
        },
    )
    task = AgentTask(
        task_id="task:formalizer_validation_failure",
        owner_subsystem="FormalizationEvaluator",
        objective="record formalizer validator failure as runtime learning",
        inputs={
            "question": question_payload,
            "theory_packet_id": "theory_packet:test",
            "simulation_manifest_id": "simulation_manifest:test",
            "algorithm_sandbox_manifest_id": "algorithm_sandbox_manifest:test",
            "environment_feedback": {
                "target_shape_contract": {
                    "contract_kind": "source_theorem_target_preservation",
                    "required_conclusion_family": (
                        "probability_or_measure_coverage_claim"
                    ),
                },
                "candidate_reroute_options": [
                    "emit FORMAL_GAP for the source theorem if proof hole remains"
                ],
            },
        },
    )

    result = subsystem.run(task, blackboard)

    assert result.status == "REVISE"
    assert result.failure_classification == "formalizer_packet_validation_failed"
    assert result.next_task is not None
    assert result.next_task.owner_subsystem == "FormalizationEvaluator"
    assert result.next_task.task_id.startswith("formalize-repair:")
    feedback = result.next_task.inputs["environment_feedback"]
    assert feedback["failure_classification"] == "formalizer_packet_validation_failed"
    assert feedback["missing_semantic_anchor_references"] == [
        "conformal_rank",
        "conformal_covered",
        "conformal_α_total",
    ]
    assert feedback["uninstantiated_adapter_object_binders"] == [
        "conformal_rank",
        "conformal_bad_ranks",
    ]
    assert feedback["missing_source_binding_contract_metadata"] is True
    assert feedback["validation_repair_policy"]["policy_kind"] == (
        "formalizer_validation_repair_policy"
    )
    assert any(
        row["rule_id"] == "forbidden_contradiction_shortcut"
        for row in feedback["validation_repair_policy"]["rules"]
    )
    assert "guardrails" in feedback["validation_repair_policy_boundary"]
    assert any(
        "Remove unsupported contradiction shortcuts" in directive
        for directive in feedback["validation_repair_directives"]
    )
    assert any(
        "Set expected_status=NEEDS_KERNEL_CHECK" in directive
        for directive in feedback["validation_repair_directives"]
    )
    assert any(
        "Do not put prose" in directive
        and "empty lean_statement_sketch" in directive
        for directive in feedback["validation_repair_directives"]
    )
    assert feedback["target_shape_contract"]["required_conclusion_family"] == (
        "probability_or_measure_coverage_claim"
    )
    assert feedback["target_drift_repair_contract"]["contract_kind"] == (
        "source_theorem_target_two_lane_repair"
    )
    assert feedback["target_drift_repair_contract"]["source_theorem_lane"][
        "fail_closed_shape"
    ].startswith("known source theorem entry")
    assert feedback["candidate_reroute_options"] == [
        "emit FORMAL_GAP for the source theorem if proof hole remains"
    ]
    assert "absurd" in feedback["required_repair"]
    assert "expected_status=NEEDS_KERNEL_CHECK" in feedback["required_repair"]
    artifact = next(iter(result.produced_artifacts.values()))
    assert artifact["artifact_kind"] == "RuntimeFormalizerValidationFailure"
    assert artifact["missing_semantic_anchor_references"] == [
        "conformal_rank",
        "conformal_covered",
        "conformal_α_total",
    ]
    assert artifact["uninstantiated_adapter_object_binders"] == [
        "conformal_rank",
        "conformal_bad_ranks",
    ]
    assert artifact["missing_source_binding_contract_metadata"] is True
    assert artifact["validation_repair_policy"]["n_rules"] >= 3
    assert any(
        row["rule_id"] == "lean_declaration_required"
        for row in artifact["validation_repair_policy"]["rules"]
    )
    assert any(
        "Remove unsupported contradiction shortcuts" in directive
        for directive in artifact["validation_repair_directives"]
    )
    assert artifact["target_shape_contract"]["required_conclusion_family"] == (
        "probability_or_measure_coverage_claim"
    )
    assert artifact["target_drift_repair_contract"]["support_lemma_lane"][
        "forbidden_output_key"
    ].startswith("formal_targets")
    assert artifact["proof_evidence_status"] == (
        "FORMALIZER_PACKET_VALIDATION_FAILURE_NOT_PROOF_EVIDENCE"
    )
    learning_rows = _runtime_learning_rows(
        [{"blackboard": {"artifacts": result.produced_artifacts}}]
    )
    assert len(learning_rows) == 1
    assert learning_rows[0]["learning_task"] == "formalizer_packet_validation_feedback"
    assert learning_rows[0]["input_summary"]["failure_classification"] == (
        "formalizer_packet_validation_failed"
    )
    assert learning_rows[0]["input_summary"]["missing_semantic_anchor_references"] == [
        "conformal_rank",
        "conformal_covered",
        "conformal_α_total",
    ]
    assert learning_rows[0]["input_summary"][
        "uninstantiated_adapter_object_binders"
    ] == ["conformal_rank", "conformal_bad_ranks"]
    assert (
        learning_rows[0]["input_summary"]["missing_source_binding_contract_metadata"]
        is True
    )
    assert any(
        "Remove unsupported contradiction shortcuts" in directive
        for directive in learning_rows[0]["input_summary"][
            "validation_repair_directives"
        ]
    )
    assert learning_rows[0]["input_summary"]["target_shape_contract"][
        "required_conclusion_family"
    ] == "probability_or_measure_coverage_claim"
    assert learning_rows[0]["input_summary"]["target_drift_repair_contract"][
        "source_theorem_lane"
    ]["output_key"] == "formal_targets"
    assert "local Lean/AXLE kernel verification" in learning_rows[0]["acceptance_gate"]


def test_formalizer_validation_failure_routes_materialization_contract() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    exc = PacketValidationError(
        validation_label="LLM Formalizer/ProofEngineer packet",
        attempts=2,
        errors=[
            (
                "source_theorem_exact_candidate_materialization_required requires "
                "a concrete source-theorem formal_targets entry with "
                "expected_status=NEEDS_KERNEL_CHECK, nonempty Lean theorem/lemma "
                "sketch, and source_theorem_target_provenance. "
                "source_theorem_target_known=true; FORMAL_GAP and helper/support "
                "candidates do not satisfy this materialization gate"
            )
        ],
        history=[{"attempt_index": 1, "ok": False}],
    )
    task = AgentTask(
        task_id="formalize:aipw_materialization",
        owner_subsystem="FormalizationEvaluator",
        objective="materialize exact source theorem candidate",
        inputs={},
    )

    result = runtime_module._formalizer_packet_validation_failure_result(
        task=task,
        question=question,
        theory_packet_id="theory_packet:test",
        simulation_manifest_id="simulation_manifest:test",
        algorithm_sandbox_manifest_id="algorithm_sandbox_manifest:test",
        proof_bank_runtime_memory_summary={
            "source_theorem_candidate_materialization_required": True,
            "recommended_formalizer_target_mode": (
                "source_theorem_exact_candidate_materialization_required"
            ),
            "source_theorem_candidate_materialization_required_target_names": [
                "thm_aipw_normality"
            ],
            "source_theorem_candidate_materialization_required_target_ids": [
                "aipw_asymptotic_normality"
            ],
            "source_theorem_candidate_materialization_required_statuses": [
                "SIGNATURE_PROBE_BLOCKED_NEEDS_CANDIDATE_ARTIFACT"
            ],
        },
        exc=exc,
    )

    artifact = next(iter(result.produced_artifacts.values()))
    feedback = result.next_task.inputs["environment_feedback"]  # type: ignore[union-attr]
    contract = feedback["source_theorem_candidate_materialization_contract"]

    assert result.status == "REVISE"
    assert result.next_task is not None
    assert "materialization candidate" in result.next_task.objective
    assert contract["contract_kind"] == (
        "source_theorem_candidate_materialization_required"
    )
    assert contract["target_ids"] == ["aipw_asymptotic_normality"]
    assert contract["target_names"] == ["thm_aipw_normality"]
    assert feedback["target_ids"] == ["aipw_asymptotic_normality"]
    assert "FORMAL_GAP-only" in feedback["required_repair"]
    assert "helper-only" in feedback["required_repair"]
    assert "expected_status=FORMAL_GAP with an empty Lean sketch" not in feedback[
        "required_repair"
    ]
    assert artifact["target_ids"] == ["aipw_asymptotic_normality"]
    assert artifact["learning_rows"][0]["input_summary"][
        "source_theorem_candidate_materialization_contract"
    ]["target_ids"] == ["aipw_asymptotic_normality"]
    problem = ProblemFormalizer().formalize(question)
    _procedures, theorem_goals = TheoryPlanner().plan(problem)
    prompt = build_formalizer_prompt(
        question=question,
        theory_packet=_runtime_sample_response(),
        simulation_manifest={"manifest_id": "simulation_manifest:test"},
        algorithm_manifest={"manifest_id": "algorithm_sandbox_manifest:test"},
        registered_problem={"question_id": question.id, "problem_class": "aipw"},
        theorem_goals=theorem_goals,
        proof_bank_obligation_catalog=[],
        proof_bank_runtime_memory_summary={},
        environment_feedback=feedback,
    )

    assert "source_theorem_candidate_materialization_contract" in prompt
    assert "Mandatory source-theorem candidate-materialization repair" in prompt
    assert "Requested target id/name(s): aipw_asymptotic_normality" in prompt


def test_formalizer_runtime_enforces_lean_candidate_required_from_learning_memory() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    question_payload = {
        "id": question.id,
        "title": question.title,
        "description": question.description,
        "tags": list(question.tags),
    }
    memory = {
        "schema_version": 1,
        "artifact_kind": "RuntimeLearningMemoryContext",
        "rows": [
            {
                "schema_version": 1,
                "question_id": question.id,
                "artifact_kind": "RuntimeLearningRow",
                "learning_task": "coding_agent_generated_code_capability_feedback",
                "capability_id": "formalizer_lean_candidate_checked_locally",
                "next_owner_subsystem": "FormalizationEvaluator",
                "target_behavior": (
                    "Produce a Claude/OpenAI-generated Lean candidate and check it "
                    "with local Lean/AXLE diagnostics inside AgentRuntime."
                ),
                "proof_evidence_status": (
                    "CODING_AGENT_CAPABILITY_FEEDBACK_NOT_PROOF_EVIDENCE"
                ),
            }
        ],
    }

    class NoLeanCandidateFormalizer:
        def __init__(self) -> None:
            self.seen_feedback: dict[str, object] = {}

        def propose(self, **kwargs: object) -> dict[str, object]:
            feedback = kwargs.get("environment_feedback", {})
            self.seen_feedback = dict(feedback) if isinstance(feedback, dict) else {}
            return {
                "schema_version": 1,
                "artifact_kind": "FormalizerProofEngineerProposalPacket",
                "packet_id": "formalizer_proposal:no_lean_candidate",
                "source_agent": "NoLeanCandidateFormalizer",
                "formal_targets": [
                    {
                        "id": "split_conformal_finite_sample_coverage",
                        "informal_source": "coverage source theorem remains open",
                        "lean_statement_sketch": "",
                        "expected_status": "FORMAL_GAP",
                    }
                ],
                "lemma_dependency_plan": [],
                "retrieval_queries": [],
                "proof_search_plan": {
                    "preferred_tools": ["local_lean"],
                    "kernel_check_plan": [],
                    "known_blockers": ["no Lean candidate emitted"],
                },
                "proof_bank_obligation_requests": [],
                "gap_taxonomy": [],
                "critic_findings": [],
                "next_actions": [],
                "proof_evidence_status": "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE",
                "kernel_verified": False,
                "full_frontier_theorem_proved": False,
            }

    proposal_agent = NoLeanCandidateFormalizer()
    subsystem = FormalizationEvaluatorRuntimeSubsystem(
        proposal_agent=proposal_agent,  # type: ignore[arg-type]
        proof_verifier=MockProofVerifier(),
        max_proof_obligations=0,
    )
    blackboard = BlackboardState(
        project_id="test",
        artifacts={
            "theory_packet:test": _runtime_sample_response(),
            "simulation_manifest:test": {"manifest_id": "simulation_manifest:test"},
            "algorithm_sandbox_manifest:test": {
                "manifest_id": "algorithm_sandbox_manifest:test"
            },
        },
    )
    task = AgentTask(
        task_id="task:formalizer_memory_requires_lean_candidate",
        owner_subsystem="FormalizationEvaluator",
        objective="Learning memory requires a live generated Lean candidate.",
        inputs={
            "question": question_payload,
            "theory_packet_id": "theory_packet:test",
            "simulation_manifest_id": "simulation_manifest:test",
            "algorithm_sandbox_manifest_id": "algorithm_sandbox_manifest:test",
            "architect_context": {"runtime_learning_memory": memory},
        },
    )

    result = subsystem.run(task, blackboard)
    failure = next(
        artifact
        for artifact in result.produced_artifacts.values()
        if artifact.get("artifact_kind") == "RuntimeFormalizerValidationFailure"
    )

    assert proposal_agent.seen_feedback["runtime_requested_evidence_contract"][
        "capability_eval_requires_formalizer_lean_candidate"
    ] is True
    assert proposal_agent.seen_feedback["runtime_requested_evidence_contract"][
        "capability_eval_requires_formalizer_local_lean_check"
    ] is True
    assert result.status == "REVISE"
    assert result.failure_classification == "formalizer_packet_validation_failed"
    assert failure["failure_classification"] == "formalizer_packet_validation_failed"
    assert any(
        "capability_eval requires at least one Claude/OpenAI-generated Lean"
        in error
        for error in failure["validation_errors"]
    )
    assert result.next_task is not None
    assert result.next_task.owner_subsystem == "FormalizationEvaluator"
    next_context = result.next_task.inputs["architect_context"]
    assert next_context["runtime_requested_evidence_contract"][
        "capability_eval_requires_formalizer_lean_candidate"
    ] is True
    feedback = result.next_task.inputs["environment_feedback"]
    assert feedback["failure_classification"] == "formalizer_packet_validation_failed"
    learning_rows = _runtime_learning_rows(
        [{"blackboard": {"artifacts": result.produced_artifacts}}]
    )
    assert any(
        row["learning_task"] == "formalizer_packet_validation_feedback"
        and row["input_summary"]["failure_classification"]
        == "formalizer_packet_validation_failed"
        for row in learning_rows
    )


