def test_runtime_learning_memory_replays_formalizer_candidate_proof_state_to_prompt(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    learning_path = tmp_path / "runtime_learning_rows.jsonl"
    learning_path.write_text(
        json.dumps(
            {
                "schema_version": 1,
                "question_id": question.id,
                "artifact_kind": "RuntimeLearningRow",
                "learning_task": "formalizer_lean_candidate_proof_state_feedback",
                "source_manifest_id": (
                    "formalizer_lean_candidate_proof_state_feedback:bad"
                ),
                "source_materialization_manifest_id": (
                    "formalizer_lean_candidate_materialization:bad"
                ),
                "target_ids": ["split_conformal_finite_sample_coverage"],
                "target_theorem_goal_ids": [
                    "split_conformal_finite_sample_coverage"
                ],
                "target_theorem_name": "split_conformal_finite_sample_coverage",
                "next_owner_subsystem": "ProofEngineer",
                "input_summary": {
                    "trigger": "FORMALIZER_LEAN_CANDIDATE_PROOF_STATE_FEEDBACK",
                    "provider_name": "local_lean_proof_state_feedback",
                    "n_feedback_rows": 1,
                    "residual_goals": [
                        "⊢ P {ω | s (Fin.last m) ω ≤ q_hat ω} ≥ ENNReal.ofReal (1 - alpha)"
                    ],
                    "diagnostics": [
                        "timeout after 60s while trying aesop on broad source theorem"
                    ],
                    "requested_tools": [
                        "lean_diagnostic_messages",
                        "lean_goal",
                        "lean_state_search",
                        "lean_multi_attempt",
                    ],
                    "executed_tools": [
                        "local.lake_env_lean",
                        "lean_diagnostic_messages",
                    ],
                    "tool_call_trace": [
                        {
                            "tool": "local.lake_env_lean",
                            "status": "local_lean_failed",
                            "returncode": -1,
                        }
                    ],
                    "attempt_status": "LOCAL_LEAN_FAILED",
                    "lean_lsp_mcp_live_called": False,
                },
                "target_behavior": (
                    "ProofEngineer should consume the exact materialized Lean "
                    "candidate artifact and proof-state diagnostics."
                ),
                "acceptance_gate": (
                    "A subsequent formalize-lean-repair task reruns through local Lean."
                ),
                "proof_evidence_status": (
                    "FORMALIZER_LEAN_CANDIDATE_PROOF_STATE_LEARNING_NOT_PROOF_EVIDENCE"
                ),
            }
        )
        + "\n",
        encoding="utf-8",
    )

    memory = _load_runtime_learning_memory([learning_path])
    summary = _formalizer_proof_bank_runtime_memory_summary(
        context={"runtime_learning_memory": memory},
        proof_bank_obligation_catalog=[],
        theorem_goals=[],
        memory_kernel_verified_proof_obligation_ids=(),
        memory_prioritized_proof_obligation_ids=(),
    )

    assert summary["formalizer_lean_candidate_proof_state_feedback_available"] is True
    proof_state_memory = summary[
        "formalizer_lean_candidate_proof_state_feedback_memory"
    ]
    assert proof_state_memory[0]["source_materialization_manifest_id"] == (
        "formalizer_lean_candidate_materialization:bad"
    )
    assert proof_state_memory[0]["target_ids"] == [
        "split_conformal_finite_sample_coverage"
    ]
    assert proof_state_memory[0]["target_theorem_goal_ids"] == [
        "split_conformal_finite_sample_coverage"
    ]
    assert proof_state_memory[0]["target_theorem_name"] == (
        "split_conformal_finite_sample_coverage"
    )
    assert proof_state_memory[0]["requested_tools"] == [
        "lean_diagnostic_messages",
        "lean_goal",
        "lean_state_search",
        "lean_multi_attempt",
    ]
    assert proof_state_memory[0]["executed_tools"] == [
        "local.lake_env_lean",
        "lean_diagnostic_messages",
    ]
    assert proof_state_memory[0]["tool_call_trace"][0]["tool"] == (
        "local.lake_env_lean"
    )

    prompt = build_formalizer_prompt(
        question=question,
        theory_packet=_runtime_sample_response(),
        simulation_manifest={"manifest_id": "simulation_manifest:test"},
        algorithm_manifest={"manifest_id": "algorithm_sandbox_manifest:test"},
        registered_problem={"question_id": question.id, "problem_class": "conformal"},
        theorem_goals=[],
        proof_bank_obligation_catalog=[],
        proof_bank_runtime_memory_summary=summary,
    )

    assert "formalizer_lean_candidate_proof_state_feedback_memory" in prompt
    assert "Prior Formalizer Lean-candidate proof-state feedback is active" in prompt
    assert "ProofEngineer repair context" in prompt
    assert "lean_goal" in prompt
    assert "lean_state_search" in prompt
    assert "lean_multi_attempt" in prompt
    assert "executed_tools" in prompt
    assert "local.lake_env_lean" in prompt
    assert "LOCAL_LEAN_FAILED" in prompt
    assert "timeout after 60s" in prompt
    assert "⊢ P {ω | s (Fin.last m) ω ≤ q_hat ω}" in prompt
    assert "FORMALIZER_LEAN_CANDIDATE_PROOF_STATE_LEARNING_NOT_PROOF_EVIDENCE" in prompt


