def test_formalization_revises_formalizer_after_local_lean_candidate_failure(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    question_payload = {
        "id": question.id,
        "title": question.title,
        "description": question.description,
        "tags": list(question.tags),
    }

    class BadLeanFormalizer:
        def __init__(self) -> None:
            self.seen_environment_feedback: list[dict[str, object]] = []

        def propose(self, **kwargs: object) -> dict[str, object]:
            feedback = kwargs.get("environment_feedback", {})
            self.seen_environment_feedback.append(
                dict(feedback) if isinstance(feedback, dict) else {}
            )
            return {
                "schema_version": 1,
                "artifact_kind": "FormalizerProofEngineerProposalPacket",
                "packet_id": "formalizer_proposal:bad_local_lean_candidate",
                "source_agent": "BadLeanFormalizer",
                "formal_targets": [
                    {
                        "id": "bad_local_lean_candidate",
                        "informal_source": "deliberately unknown Lean identifier",
                        "lean_statement_sketch": (
                            "theorem bad_local_lean_candidate : "
                            "DefinitelyUnknownLeanIdentifier := by\n"
                            "  trivial\n"
                        ),
                        "expected_status": "NEEDS_KERNEL_CHECK",
                    }
                ],
                "lemma_dependency_plan": [],
                "retrieval_queries": [],
                "proof_search_plan": {
                    "preferred_tools": ["local_lean"],
                    "kernel_check_plan": ["run local Lean"],
                    "known_blockers": [],
                },
                "proof_bank_obligation_requests": [],
                "gap_taxonomy": [],
                "critic_findings": [],
                "next_actions": [],
                "proof_evidence_status": "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE",
                "kernel_verified": False,
                "full_frontier_theorem_proved": False,
            }

    class FakeCandidateProofStateProvider:
        name = "fake_candidate_proof_state_provider"

        def inspect(self, subclaims: list[FormalSubclaim]) -> list[ProofStateFeedbackRow]:
            return [
                ProofStateFeedbackRow(
                    schema_version=1,
                    feedback_id="proof_state_feedback:test_candidate",
                    subclaim_id=subclaims[0].id if subclaims else "",
                    proof_obligation_id=(
                        subclaims[0].proof_obligation_id if subclaims else ""
                    )
                    or "",
                    claim_type=subclaims[0].claim_type if subclaims else "lean_obligation",
                    provider_name=self.name,
                    provider_preferences=("lean_lsp_mcp", "local_lean"),
                    requested_tools=("lean_goal", "lean_state_search"),
                    attempt_status="candidate_goal_feedback_recorded",
                    diagnostics=("goal feedback for materialized candidate",),
                    residual_goals=("repair unknown identifier in candidate",),
                    route_revision_recommended=True,
                    subclaim_status=subclaims[0].status if subclaims else "FAILED",
                    subclaim_kernel_verified=False,
                    local_lean_checked=False,
                    local_lean_returncode=None,
                    proof_evidence_status=PROOF_STATE_FEEDBACK_STATUS,
                    proof_evidence_boundary="diagnostic only",
                    created_at="2026-01-01T00:00:00+00:00",
                    executed_tools=("lean_lsp_mcp.lean_diagnostic_messages",),
                    tool_call_trace=(
                        {
                            "tool": "lean_lsp_mcp.lean_diagnostic_messages",
                            "status": "mcp_tool_call_succeeded",
                            "proof_evidence_status": PROOF_STATE_FEEDBACK_STATUS,
                        },
                    ),
                )
            ] if subclaims else []

    formalizer = BadLeanFormalizer()
    subsystem = FormalizationEvaluatorRuntimeSubsystem(
        proposal_agent=formalizer,
        proof_verifier=MockProofVerifier(),
        proof_state_provider=FakeCandidateProofStateProvider(),
        max_proof_obligations=0,
        lean_candidate_root=tmp_path / "formalizer_lean_candidates",
        lean_candidate_local_lean=True,
    )
    blackboard = BlackboardState(
        project_id="test",
        artifacts={
            "theory_packet:test": _runtime_sample_response(),
            "simulation_manifest:test": {"manifest_id": "simulation_manifest:test"},
            "algorithm_sandbox_manifest:test": {
                "manifest_id": "algorithm_sandbox_manifest:test"
            },
        },
    )
    task = AgentTask(
        task_id="task:formalization_bad_local_lean_candidate",
        owner_subsystem="FormalizationEvaluator",
        objective="route failed local Lean diagnostics back to Formalizer",
        inputs={
            "question": question_payload,
            "theory_packet_id": "theory_packet:test",
            "simulation_manifest_id": "simulation_manifest:test",
            "algorithm_sandbox_manifest_id": "algorithm_sandbox_manifest:test",
        },
    )

    result = subsystem.run(task, blackboard)

    assert result.status == "REVISE"
    assert result.failure_classification == (
        "formalizer_lean_candidate_local_lean_failed"
    )
    assert result.next_task is not None
    assert result.next_task.owner_subsystem == "ProofEngineer"
    assert result.next_task.task_id.startswith("formalize-lean-repair:")
    assert "local_lean" in result.next_task.allowed_tools
    assert "proof_search" in result.next_task.allowed_tools
    candidate_feedback_manifests = [
        artifact
        for artifact in result.produced_artifacts.values()
        if isinstance(artifact, dict)
        and artifact.get("artifact_kind")
        == "RuntimeFormalizerLeanCandidateProofStateFeedbackManifest"
    ]
    assert len(candidate_feedback_manifests) == 1
    candidate_feedback_manifest = candidate_feedback_manifests[0]
    assert candidate_feedback_manifest["provider_name"] == (
        "fake_candidate_proof_state_provider"
    )
    assert candidate_feedback_manifest["counts"]["rows"] == 1
    assert candidate_feedback_manifest["lean_lsp_mcp_live_called"] is True
    assert candidate_feedback_manifest["counts"]["lean_lsp_mcp_tool_calls"] == 1
    assert candidate_feedback_manifest["proof_evidence_status"] == (
        "FORMALIZER_LEAN_CANDIDATE_PROOF_STATE_FEEDBACK_NOT_PROOF_EVIDENCE"
    )
    assert any(
        obs.observation_type == "formalizer_lean_candidate_proof_state_feedback"
        for obs in result.observations
    )
    assert any(
        tool.tool_name
        == "ProofStateFeedbackProvider.inspect_formalizer_lean_candidate"
        for tool in result.tool_calls
    )
    assert any(
        entry.evidence_type == "formalizer_lean_candidate_proof_state_feedback"
        for entry in result.evidence_entries
    )
    learning_rows = _runtime_learning_rows(
        [{"blackboard": {"artifacts": result.produced_artifacts}}]
    )
    candidate_feedback_learning_rows = [
        row
        for row in learning_rows
        if row.get("learning_task")
        == "formalizer_lean_candidate_proof_state_feedback"
    ]
    assert len(candidate_feedback_learning_rows) == 1
    assert candidate_feedback_learning_rows[0]["next_owner_subsystem"] == (
        "ProofEngineer"
    )
    assert "lean_goal" in candidate_feedback_learning_rows[0]["input_summary"][
        "requested_tools"
    ]
    assert candidate_feedback_learning_rows[0]["proof_evidence_status"] == (
        "FORMALIZER_LEAN_CANDIDATE_PROOF_STATE_LEARNING_NOT_PROOF_EVIDENCE"
    )
    feedback = result.next_task.inputs["environment_feedback"]
    assert feedback["feedback_type"] == (
        "formalizer_lean_candidate_local_lean_feedback"
    )
    assert feedback["repair_owner_agent"] == "ProofEngineer"
    assert feedback["proofengineer_repair_context"]["candidate_artifact_paths"]
    assert feedback["proofengineer_repair_context"]["candidate_rerun_specs"]
    assert "local_lean" in feedback["proofengineer_repair_context"][
        "available_runtime_tools"
    ]
    proofengineer_context = feedback["proofengineer_repair_context"]
    rerun_spec = proofengineer_context["candidate_rerun_specs"][0]
    assert rerun_spec["candidate_id"] == "bad_local_lean_candidate"
    assert rerun_spec["artifact_path"] == proofengineer_context[
        "candidate_artifact_paths"
    ][0]
    assert rerun_spec["target_lean_declaration"] == "bad_local_lean_candidate"
    assert rerun_spec["local_lean_command"]
    assert rerun_spec["local_lean_timeout"] > 0
    assert "local_lean_command_project_timeout" in proofengineer_context[
        "verifier_feedback_sources"
    ]
    assert proofengineer_context["proof_state_workflow"]["style"] == (
        "lean_dojo_reprover_compatible"
    )
    assert "lean_state_search" in proofengineer_context["proof_state_workflow"][
        "preferred_tool_order"
    ]
    assert "lean_multi_attempt" in proofengineer_context["proof_state_workflow"][
        "preferred_tool_order"
    ]
    assert proofengineer_context["retrieval_query_seeds"]
    assert proofengineer_context["candidate_proof_state_provider"] == (
        "fake_candidate_proof_state_provider"
    )
    assert proofengineer_context["candidate_proof_state_feedback_counts"]["rows"] == 1
    assert proofengineer_context["candidate_proof_state_feedback_rows"][0][
        "requested_tools"
    ] == ("lean_goal", "lean_state_search")
    assert proofengineer_context["n_live_proof_state_requests"] == 1
    live_request = proofengineer_context["live_proof_state_requests"][0]
    assert live_request["provider_preferences"][0] == "lean_lsp_mcp"
    assert live_request["target_lean_declaration"] == "bad_local_lean_candidate"
    assert live_request["target_lean_line"] == 1
    assert {
        row["tool"] for row in live_request["mcp_tool_calls"]
    } >= {"lean_goal", "lean_diagnostic_messages", "lean_multi_attempt"}
    assert feedback["n_local_lean_checked"] == 1
    assert feedback["n_local_lean_compiled"] == 0
    assert feedback["formalizer_lean_repair_retry_depth"] == 0
    assert feedback["repeated_formalizer_lean_candidate_failure"] is False
    diagnostics = feedback["candidate_diagnostics"]
    assert diagnostics[0]["candidate_id"] == "bad_local_lean_candidate"
    assert diagnostics[0]["local_lean_attempted"] is True
    assert diagnostics[0]["local_lean_compiled"] is False
    assert "DefinitelyUnknownLeanIdentifier" in diagnostics[0][
        "local_lean_stdout_excerpt"
    ]
    repair_prompt = build_formalizer_prompt(
        question=question,
        theory_packet=_runtime_sample_response(),
        simulation_manifest={"manifest_id": "simulation_manifest:test"},
        algorithm_manifest={"manifest_id": "algorithm_sandbox_manifest:test"},
        registered_problem={"question_id": question.id, "problem_class": "conformal"},
        theorem_goals=[],
        proof_bank_obligation_catalog=[],
        proof_bank_runtime_memory_summary={},
        environment_feedback=feedback,
    )
    assert "formalizer_lean_candidate_local_lean_feedback" in repair_prompt
    assert "ProofEngineer repair loop is active" in repair_prompt
    assert "proofengineer_repair_context" in repair_prompt
    assert "candidate_rerun_specs" in repair_prompt
    assert "local_lean_command" in repair_prompt
    assert "local_lean" in repair_prompt
    assert "proof_search" in repair_prompt
    assert "lean_state_search" in repair_prompt
    assert "lean_multi_attempt" in repair_prompt
    assert "live_proof_state_requests" in repair_prompt
    assert "retrieval_query_seeds" in repair_prompt
    assert "DefinitelyUnknownLeanIdentifier" in repair_prompt
    assert any(
        obs.observation_type == "formalizer_lean_candidate_local_lean_feedback"
        for obs in result.observations
    )

    retry_result = subsystem.run(result.next_task, blackboard)
    retry_feedback = retry_result.next_task.inputs["environment_feedback"]
    assert retry_feedback["formalizer_lean_repair_retry_depth"] == 1
    assert retry_feedback["repeated_formalizer_lean_candidate_failure"] is True
    assert formalizer.seen_environment_feedback[-1]["runtime_task"][
        "owner_subsystem"
    ] == "ProofEngineer"
    assert "lean_lsp_mcp" in formalizer.seen_environment_feedback[-1][
        "runtime_task"
    ]["allowed_tools"]
    assert formalizer.seen_environment_feedback[-1]["repair_owner_agent"] == (
        "ProofEngineer"
    )


def test_agent_runtime_yields_formalizer_lean_repair_budget_to_gap_planner(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    question_payload = {
        "id": question.id,
        "title": question.title,
        "description": question.description,
        "tags": list(question.tags),
    }

    class BadLeanFormalizer:
        def propose(self, **_kwargs: object) -> dict[str, object]:
            return {
                "schema_version": 1,
                "artifact_kind": "FormalizerProofEngineerProposalPacket",
                "packet_id": "formalizer_proposal:gap_planner_yield_bad_lean",
                "source_agent": "BadLeanFormalizer",
                "formal_targets": [
                    {
                        "id": "gap_planner_yield_bad_lean",
                        "informal_source": "deliberately unknown Lean identifier",
                        "lean_statement_sketch": (
                            "theorem gap_planner_yield_bad_lean : "
                            "DefinitelyUnknownLeanIdentifier := by\n"
                            "  trivial\n"
                        ),
                        "expected_status": "NEEDS_KERNEL_CHECK",
                    }
                ],
                "lemma_dependency_plan": [],
                "retrieval_queries": [],
                "proof_search_plan": {
                    "preferred_tools": ["local_lean"],
                    "kernel_check_plan": ["run local Lean"],
                    "known_blockers": [],
                },
                "proof_bank_obligation_requests": [],
                "gap_taxonomy": [],
                "critic_findings": [],
                "next_actions": [],
                "proof_evidence_status": (
                    "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE"
                ),
                "kernel_verified": False,
                "full_frontier_theorem_proved": False,
            }

    class RecordingGapPlanner:
        name = "FormalizationGapPlanner"

        def __init__(self) -> None:
            self.tasks: list[AgentTask] = []
            self.bridge_seen = False

        def run(
            self,
            task: AgentTask,
            blackboard: BlackboardState,
        ) -> AgentStepResult:
            self.tasks.append(task)
            self.bridge_seen = any(
                isinstance(artifact, dict)
                and artifact.get("artifact_kind")
                == "RuntimeFormalizationGapPlannerBridge"
                for artifact in blackboard.artifacts.values()
            )
            return AgentStepResult(
                status="ACCEPTED",
                rationale="recorded gap-planner handoff after bounded Lean repair",
            )

    blackboard = BlackboardState(
        project_id="formalizer-gap-planner-yield-test",
        artifacts={
            "theory_packet:test": _runtime_sample_response(),
            "simulation_manifest:test": {"manifest_id": "simulation_manifest:test"},
            "algorithm_sandbox_manifest:test": {
                "manifest_id": "algorithm_sandbox_manifest:test"
            },
        },
    )
    gap_planner = RecordingGapPlanner()
    runtime = AgentRuntime(
        subsystems={
            "ProofEngineer": ProofEngineerRuntimeSubsystem(
                proposal_agent=BadLeanFormalizer(),
                proof_verifier=MockProofVerifier(),
                max_proof_obligations=0,
                lean_candidate_root=tmp_path / "formalizer_lean_candidates",
                lean_candidate_local_lean=True,
            ),
            "FormalizationGapPlanner": gap_planner,
        },
        blackboard=blackboard,
    )
    initial_task = AgentTask(
        task_id="formalize-lean-repair:conformal_prediction_coverage:yield",
        owner_subsystem="ProofEngineer",
        objective="yield repeated Lean candidate failure to gap planner",
        inputs={
            "question": question_payload,
            "theory_packet_id": "theory_packet:test",
            "simulation_manifest_id": "simulation_manifest:test",
            "algorithm_sandbox_manifest_id": "algorithm_sandbox_manifest:test",
            "architect_context": {
                "runtime_evaluation_mode": "capability_eval",
                "runtime_requested_evidence_contract": {
                    "capability_eval_formalizer_lean_candidate_repair_yield_to_gap_planner_after_attempts": 1,
                },
            },
            "environment_feedback": {
                "feedback_type": "formalizer_lean_candidate_local_lean_feedback",
                "repair_owner_agent": "ProofEngineer",
            },
        },
        allowed_tools=("model_backend", "local_lean", "lean_lsp_mcp"),
    )

    result = runtime.run(initial_task, max_iterations=2)

    assert result.status == "ACCEPTED"
    assert result.traces[0].subsystem == "ProofEngineer"
    assert result.traces[0].status == "REVISE"
    assert result.traces[0].failure_classification == (
        "formalizer_lean_candidate_repair_budget_yield_to_gap_planner"
    )
    assert result.traces[0].next_task is not None
    assert result.traces[0].next_task.owner_subsystem == "FormalizationGapPlanner"
    assert result.traces[1].subsystem == "FormalizationGapPlanner"
    assert len(gap_planner.tasks) == 1
    assert gap_planner.bridge_seen is True

    yielded_task = gap_planner.tasks[0]
    feedback = yielded_task.inputs["environment_feedback"]
    assert feedback["feedback_type"] == (
        "formalizer_lean_candidate_repair_budget_gap_planner_handoff"
    )
    assert feedback["failure_classification"] == (
        "formalizer_lean_candidate_repair_budget_yield_to_gap_planner"
    )
    assert feedback["formalizer_lean_repair_attempts_used"] == 1
    assert (
        feedback["formalizer_lean_repair_yield_to_gap_planner_after_attempts"]
        == 1
    )
    assert feedback["proof_evidence_status"] == (
        "FORMALIZER_LEAN_REPAIR_GAP_PLANNER_YIELD_NOT_PROOF_EVIDENCE"
    )
    assert feedback["formalization_gap_planner_bridge_ids"]
    assert (
        yielded_task.inputs["architect_context"]["runtime_feedback_loop"][
            "handoff"
        ]
        == "formalizer_lean_candidate_repair_budget_yield_to_gap_planner"
    )
    assert any(
        obs.observation_type
        == "formalizer_lean_candidate_repair_budget_yield_to_gap_planner"
        for obs in result.traces[0].observations
    )


def test_formalizer_live_prover_inspects_compiled_candidate_when_required(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    question_payload = {
        "id": question.id,
        "title": question.title,
        "description": question.description,
        "tags": list(question.tags),
    }

    class CompilingLeanFormalizer:
        def propose(self, **kwargs: object) -> dict[str, object]:
            return {
                "schema_version": 1,
                "artifact_kind": "FormalizerProofEngineerProposalPacket",
                "packet_id": "formalizer_proposal:compiled_live_prover_candidate",
                "source_agent": "CompilingLeanFormalizer",
                "formal_targets": [
                    {
                        "id": "compiled_live_prover_candidate",
                        "informal_source": "minimal compiled candidate for live prover inspection",
                        "lean_statement_sketch": (
                            "theorem compiled_live_prover_candidate "
                            "(support target : Prop) "
                            "(h : support -> target) (hs : support) : "
                            "target := by\n"
                            "  exact h hs\n"
                        ),
                        "expected_status": "NEEDS_KERNEL_CHECK",
                        "source_theorem_target_provenance": {
                            "source_theorem_target_known": False,
                            "target_lean_declaration": "",
                            "source_theorem_goal_id": "",
                        },
                    }
                ],
                "lemma_dependency_plan": [],
                "retrieval_queries": [],
                "proof_search_plan": {
                    "preferred_tools": ["lean_lsp_mcp", "local_lean"],
                    "kernel_check_plan": ["run local Lean", "inspect with Lean LSP"],
                    "known_blockers": [],
                },
                "proof_bank_obligation_requests": [],
                "gap_taxonomy": [],
                "critic_findings": [],
                "next_actions": [],
                "proof_evidence_status": "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE",
                "kernel_verified": False,
                "full_frontier_theorem_proved": False,
            }

    class FakeLiveCandidateProofStateProvider:
        name = "lean_lsp_mcp_proof_state_feedback"

        def inspect(self, subclaims: list[FormalSubclaim]) -> list[ProofStateFeedbackRow]:
            assert subclaims
            if not subclaims[0].id.startswith("formalizer_lean_candidate:"):
                return [
                    ProofStateFeedbackRow(
                        schema_version=1,
                        feedback_id="proof_state_feedback:general_subclaim",
                        subclaim_id=subclaims[0].id,
                        proof_obligation_id=subclaims[0].proof_obligation_id or "",
                        claim_type=subclaims[0].claim_type,
                        provider_name=self.name,
                        provider_preferences=("lean_lsp_mcp", "local_lean"),
                        requested_tools=("lean_diagnostic_messages",),
                        attempt_status="general_subclaim_feedback_recorded",
                        diagnostics=("general proof-state feedback",),
                        residual_goals=(),
                        route_revision_recommended=False,
                        subclaim_status=subclaims[0].status,
                        subclaim_kernel_verified=subclaims[0].kernel_verified,
                        local_lean_checked=False,
                        local_lean_returncode=None,
                        proof_evidence_status=PROOF_STATE_FEEDBACK_STATUS,
                        proof_evidence_boundary=PROOF_STATE_FEEDBACK_BOUNDARY,
                        created_at="2026-01-01T00:00:00+00:00",
                    )
                ]
            assert subclaims[0].artifact_path
            return [
                ProofStateFeedbackRow(
                    schema_version=1,
                    feedback_id="proof_state_feedback:compiled_live_candidate",
                    subclaim_id=subclaims[0].id,
                    proof_obligation_id=subclaims[0].proof_obligation_id or "",
                    claim_type=subclaims[0].claim_type,
                    provider_name=self.name,
                    provider_preferences=("lean_lsp_mcp", "local_lean"),
                    requested_tools=("lean_diagnostic_messages", "lean_goal"),
                    attempt_status="candidate_live_prover_inspection_recorded",
                    diagnostics=("compiled candidate inspected by live prover",),
                    residual_goals=(),
                    route_revision_recommended=False,
                    subclaim_status=subclaims[0].status,
                    subclaim_kernel_verified=subclaims[0].kernel_verified,
                    local_lean_checked=False,
                    local_lean_returncode=None,
                    proof_evidence_status=PROOF_STATE_FEEDBACK_STATUS,
                    proof_evidence_boundary=PROOF_STATE_FEEDBACK_BOUNDARY,
                    created_at="2026-01-01T00:00:00+00:00",
                    executed_tools=("lean_lsp_mcp.lean_diagnostic_messages",),
                    tool_call_trace=(
                        {
                            "tool": "lean_lsp_mcp.lean_diagnostic_messages",
                            "status": "mcp_tool_call_succeeded",
                            "proof_evidence_status": PROOF_STATE_FEEDBACK_STATUS,
                        },
                    ),
                    artifact_path=str(subclaims[0].artifact_path),
                )
            ]

    subsystem = FormalizationEvaluatorRuntimeSubsystem(
        proposal_agent=CompilingLeanFormalizer(),  # type: ignore[arg-type]
        proof_verifier=MockProofVerifier(),
        proof_state_provider=FakeLiveCandidateProofStateProvider(),
        max_proof_obligations=0,
        lean_candidate_root=tmp_path / "formalizer_lean_candidates",
        lean_candidate_local_lean=True,
    )
    blackboard = BlackboardState(
        project_id="test",
        artifacts={
            "theory_packet:test": _runtime_sample_response(),
            "simulation_manifest:test": {"manifest_id": "simulation_manifest:test"},
            "algorithm_sandbox_manifest:test": {
                "manifest_id": "algorithm_sandbox_manifest:test"
            },
        },
    )
    task = AgentTask(
        task_id="task:formalization_compiled_candidate_live_prover",
        owner_subsystem="FormalizationEvaluator",
        objective="Inspect a compiled materialized candidate with live prover tools.",
        inputs={
            "question": question_payload,
            "theory_packet_id": "theory_packet:test",
            "simulation_manifest_id": "simulation_manifest:test",
            "algorithm_sandbox_manifest_id": "algorithm_sandbox_manifest:test",
            "architect_context": {
                "runtime_requested_evidence_contract": {
                    "capability_eval_requires_formalizer_lean_candidate": True,
                    "capability_eval_requires_formalizer_local_lean_check": True,
                    "capability_eval_requires_formalizer_proof_state_request": True,
                    "capability_eval_requires_formalizer_proof_state_feedback": True,
                    "capability_eval_requires_formalizer_live_prover_tool_call": True,
                }
            },
        },
    )

    result = subsystem.run(task, blackboard)

    candidate_feedback_manifests = [
        artifact
        for artifact in result.produced_artifacts.values()
        if isinstance(artifact, dict)
        and artifact.get("artifact_kind")
        == "RuntimeFormalizerLeanCandidateProofStateFeedbackManifest"
    ]
    assert len(candidate_feedback_manifests) == 1
    candidate_feedback_manifest = candidate_feedback_manifests[0]
    assert candidate_feedback_manifest["lean_lsp_mcp_live_called"] is True
    assert (
        candidate_feedback_manifest["counts"]["lean_lsp_mcp_tool_calls"] == 1
    )
    assert any(
        obs.observation_type == "formalizer_lean_candidate_proof_state_feedback"
        and obs.payload["lean_lsp_mcp_live_called"] is True
        for obs in result.observations
    )
    assert any(
        tool.tool_name
        == "ProofStateFeedbackProvider.inspect_formalizer_lean_candidate"
        and tool.inputs["lean_lsp_mcp_live_called"] is True
        for tool in result.tool_calls
    )
    assert any(
        entry.evidence_type == "formalizer_lean_candidate_proof_state_feedback"
        and entry.payload["lean_lsp_mcp_live_called"] is True
        for entry in result.evidence_entries
    )


def test_agent_runtime_dispatches_proofengineer_to_explicit_subsystem(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    question_payload = {
        "id": question.id,
        "title": question.title,
        "description": question.description,
        "tags": list(question.tags),
    }

    class MinimalProofEngineerFormalizer:
        def propose(self, **kwargs: object) -> dict[str, object]:
            feedback = kwargs.get("environment_feedback", {})
            assert isinstance(feedback, dict)
            assert feedback["runtime_task"]["owner_subsystem"] == "ProofEngineer"
            assert feedback["architect_subsystem_acceptance_gate"] == (
                "proofengineer-specific local Lean repair gate"
            )
            assert feedback["architect_formal_verification_policy"] == "required"
            assert feedback["architect_recommended_research_path"] == "proof_first"
            return {
                "schema_version": 1,
                "artifact_kind": "FormalizerProofEngineerProposalPacket",
                "packet_id": "formalizer_proposal:proofengineer_dispatch",
                "source_agent": "MinimalProofEngineerFormalizer",
                "formal_targets": [],
                "lemma_dependency_plan": [],
                "retrieval_queries": [],
                "proof_search_plan": {
                    "preferred_tools": ["lean_goal", "lean_multi_attempt"],
                    "kernel_check_plan": ["record explicit blocker"],
                    "known_blockers": ["dispatch smoke does not attempt theorem proof"],
                },
                "proof_bank_obligation_requests": [],
                "gap_taxonomy": [
                    {
                        "gap": "proofengineer dispatch smoke only",
                        "kind": "proof_search",
                        "next_owner": "ProofEngineer",
                    }
                ],
                "critic_findings": [
                    {
                        "critic": "dispatch_smoke",
                        "finding": "no theorem proof claimed",
                        "reroute_if_confirmed": "CriticEvaluator",
                    }
                ],
                "next_actions": [
                    {
                        "owner_agent": "CriticEvaluator",
                        "action": "summarize open formal blocker",
                        "acceptance_gate": "no kernel proof promotion",
                    }
                ],
                "proof_evidence_status": "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE",
                "kernel_verified": False,
                "full_frontier_theorem_proved": False,
            }

    blackboard = BlackboardState(
        project_id="test",
        artifacts={
            "theory_packet:test": _runtime_sample_response(),
            "simulation_manifest:test": {"manifest_id": "simulation_manifest:test"},
            "algorithm_sandbox_manifest:test": {
                "manifest_id": "algorithm_sandbox_manifest:test"
            },
        },
    )
    runtime = AgentRuntime(
        subsystems={
            "ProofEngineer": ProofEngineerRuntimeSubsystem(
                proposal_agent=MinimalProofEngineerFormalizer(),
                proof_verifier=MockProofVerifier(),
                max_proof_obligations=0,
                lean_candidate_root=tmp_path / "formalizer_lean_candidates",
            )
        },
        blackboard=blackboard,
    )
    result = runtime.run(
        AgentTask(
            task_id="formalize-lean-repair:conformal_prediction_coverage:dispatch",
            owner_subsystem="ProofEngineer",
            objective="execute the ProofEngineer repair worker, not a hidden alias",
            inputs={
                "question": question_payload,
                "theory_packet_id": "theory_packet:test",
                "simulation_manifest_id": "simulation_manifest:test",
                "algorithm_sandbox_manifest_id": "algorithm_sandbox_manifest:test",
                "environment_feedback": {
                    "feedback_type": "formalizer_lean_candidate_local_lean_feedback",
                    "repair_owner_agent": "ProofEngineer",
                },
                "architect_context": {
                    "architect_runtime_plan": {
                        "evidence_contract": {
                            "formal_verification_policy": "required",
                            "recommended_research_path": "proof_first",
                            "formal_required_for_final": True,
                        },
                        "subsystem_execution_plan": [
                            {
                                "subsystem": "FormalizationEvaluator",
                                "acceptance_gate": (
                                    "wrong formalization gate for this proof repair"
                                ),
                            },
                            {
                                "subsystem": "ProofEngineer",
                                "acceptance_gate": (
                                    "proofengineer-specific local Lean repair gate"
                                ),
                                "expected_artifacts": [
                                    "proofengineer_repair_candidate",
                                ],
                            },
                        ],
                    },
                },
            },
            allowed_tools=("model_backend", "local_lean", "lean_lsp_mcp"),
        ),
        max_iterations=1,
    )

    assert result.status == "MAX_ITERATIONS_REACHED"
    assert result.traces[0].task.owner_subsystem == "ProofEngineer"
    assert result.traces[0].subsystem == "ProofEngineer"
    assert result.traces[0].status == "REROUTE"
    assert result.traces[0].next_task is not None
    assert result.traces[0].next_task.owner_subsystem == "CriticEvaluator"
    assert not result.blackboard.active_blockers


