def test_exact_semantic_definition_lean_repair_tool_calls_do_not_satisfy_bound_formalizer_capability() -> None:
    artifacts = {
        "exact_semantic_definition_lean_repair_executor:covered": {
            "artifact_kind": (
                "SourceTheoremExactSemanticDefinitionLeanRepairExecutorManifest"
            ),
            "n_results": 1,
            "n_local_lean_checked": 1,
            "n_local_lean_compiled": 0,
            "n_local_lean_tool_calls": 1,
            "n_executed_tool_calls": 1,
            "source_theorem_kernel_verified": False,
            "semantic_definition_kernel_verified": False,
            "proof_evidence_status": (
                "EXACT_SEMANTIC_DEFINITION_LEAN_REPAIR_EXECUTION_NOT_SOURCE_THEOREM_PROOF"
            ),
        }
    }

    evidence_summary = _runtime_evidence_summary(
        [{"blackboard": {"artifacts": artifacts}}]
    )
    proof = evidence_summary["proof"]

    assert (
        proof[
            "n_source_theorem_exact_semantic_definition_lean_repair_executor_local_lean_tool_calls"
        ]
        == 1
    )
    assert proof["n_formalizer_lean_candidate_local_lean_checked"] == 1
    assert proof["n_formalizer_lean_candidate_local_lean_tool_calls"] == 1
    assert (
        proof[
            "n_formalizer_lean_candidate_materialization_bound_local_lean_tool_calls"
        ]
        == 0
    )
    table = _runtime_coding_agent_capability_table(
        {
            "n_live_generator_agents_enabled": 6,
            "n_llm_formalizer_proof_engineer_proposals": 1,
            "n_live_llm_formalizer_proof_engineer_proposals": 1,
            "n_formalizer_lean_candidate_local_lean_checked": proof[
                "n_formalizer_lean_candidate_local_lean_checked"
            ],
            "n_formalizer_lean_candidate_local_lean_tool_calls": proof[
                "n_formalizer_lean_candidate_local_lean_tool_calls"
            ],
        }
    )
    rows = {row["capability_id"]: row for row in table["rows"]}

    assert rows["formalizer_lean_candidate_checked_locally"]["passed"] is True
    assert rows["formalizer_local_lean_tool_call_observed"]["passed"] is False
    assert proof["n_kernel_verified_subclaims"] == 0
    assert proof["n_full_frontier_theorem_proved"] == 0


def test_runtime_audit_derives_formalizer_repair_sequences_from_results(
    tmp_path: Path,
) -> None:
    artifacts = {
        "formalizer_lean_candidate_materialization:fail": {
            "artifact_kind": "RuntimeFormalizerLeanCandidateMaterialization",
            "created_at": "2026-06-24T00:01:00+00:00",
            "manifest_id": "formalizer_lean_candidate_materialization:fail",
            "task_id": "formalize:conformal_prediction_coverage:initial",
            "question": {"id": "conformal_prediction_coverage"},
            "n_precheck_rejected": 1,
            "n_local_lean_checked": 0,
            "n_local_lean_compiled": 0,
            "candidate_rows": [
                {
                    "candidate_id": "target_drift",
                    "precheck_status": "REJECTED_BY_RUNTIME_PRECHECK",
                    "local_lean_attempted": False,
                    "local_lean_compiled": False,
                }
            ],
        },
        "formalizer_lean_candidate_materialization:pass": {
            "artifact_kind": "RuntimeFormalizerLeanCandidateMaterialization",
            "created_at": "2026-06-24T00:02:00+00:00",
            "manifest_id": "formalizer_lean_candidate_materialization:pass",
            "task_id": "formalize-lean-repair:conformal_prediction_coverage:repair",
            "question": {"id": "conformal_prediction_coverage"},
            "n_precheck_rejected": 0,
            "n_local_lean_checked": 1,
            "n_local_lean_compiled": 1,
            "candidate_rows": [
                {
                    "candidate_id": "compiled_repair",
                    "precheck_status": "MATERIALIZED_REQUIRES_LOCAL_LEAN_OR_AXLE",
                    "local_lean_attempted": True,
                    "local_lean_compiled": True,
                }
            ],
        },
    }
    result_path = tmp_path / "runtime_result.json"
    result_path.write_text(
        json.dumps({"blackboard": {"artifacts": artifacts}}),
        encoding="utf-8",
    )

    repair_sequences = _formalizer_lean_candidate_repair_sequences_from_result_paths(
        [result_path]
    )
    scorecard = _runtime_capability_scorecard(
        {
            "n_results": 1,
            "n_llm_formalizer_proof_engineer_proposals": 1,
            "n_live_llm_formalizer_proof_engineer_proposals": 1,
            "n_formalizer_lean_candidate_local_lean_checked": 1,
            "n_formalizer_lean_candidate_local_lean_compiled": 1,
            "n_formalizer_lean_candidate_failed_then_passed_repair_sequences": (
                repair_sequences
            ),
        }
    )
    rows = {row["requirement_id"]: row for row in scorecard["rows"]}

    assert repair_sequences == 1
    assert rows[
        "formalizer_lean_candidate_integrated_repair_loop_observed"
    ]["passed"] is True
    assert "integrated_formalizer_repair_sequences=1" in rows[
        "formalizer_lean_candidate_integrated_repair_loop_observed"
    ]["evidence"]
    assert rows["formalizer_lean_candidate_repair_component_gate"][
        "passed"
    ] is False


