def test_runtime_audit_counts_attached_live_formalizer_lsp_component(
    tmp_path: Path,
) -> None:
    runtime_dir = tmp_path / "runtime"
    runtime_dir.mkdir()
    result_path = runtime_dir / "q_runtime_result.json"
    result_path.write_text(
        json.dumps(
            {
                "status": "MAX_ITERATIONS_REACHED",
                "blackboard": {
                    "project_id": "runtime:q",
                    "artifacts": {},
                },
                "traces": [],
            }
        ),
        encoding="utf-8",
    )
    manifest = {
        "schema_version": 1,
        "runtime_evaluation_mode": "capability_eval",
        "n_questions": 1,
        "question_ids": ["q"],
        "status_counts": {"MAX_ITERATIONS_REACHED": 1},
        "artifacts": {"per_question_results": [str(result_path)]},
        "internal_formalizer_lean_candidate_repair_eval": {
            "artifact_kind": "RuntimeAttachedFormalizerLeanCandidateRepairEval",
            "manifest_path": "runs/component/formalizer_lean_candidate_repair_eval_manifest.json",
            "provider_name": "anthropic",
            "backend_provider_name": "anthropic",
            "live_generator": True,
            "static_or_fixture_only": False,
            "capability_evidence_ok": True,
            "repair_sequences": 1,
            "local_lean_checked": 1,
            "prior_feedback_proof_state_counts": {
                "local_lean_tool_calls": 1,
                "lean_lsp_mcp_tool_calls": 3,
                "executed_tool_calls": 4,
            },
        },
    }
    (runtime_dir / "research_agent_runtime_manifest.json").write_text(
        json.dumps(manifest),
        encoding="utf-8",
    )

    audit = audit_research_agent_runtime(runtime_dir, runtime_dir / "audit")
    rows = {row["requirement_id"]: row for row in audit["capability_scorecard"]["rows"]}

    assert audit["n_integrated_lean_lsp_mcp_live_calls"] == 0
    assert audit["n_lean_lsp_mcp_live_calls"] == 0
    assert audit["n_attached_formalizer_prior_feedback_lean_lsp_mcp_tool_calls"] == 3
    assert (
        audit[
            "internal_formalizer_lean_candidate_repair_eval_prior_feedback_lean_lsp_mcp_tool_calls"
        ]
        == 3
    )
    assert rows["formalizer_live_prover_tool_call_observed"]["passed"] is False
    assert rows[
        "formalizer_live_prover_tool_component_calibration"
    ]["passed"] is True

    manifest["internal_formalizer_lean_candidate_repair_eval"][
        "backend_provider_name"
    ] = "static"
    (runtime_dir / "research_agent_runtime_manifest.json").write_text(
        json.dumps(manifest),
        encoding="utf-8",
    )
    static_backend_audit = audit_research_agent_runtime(
        runtime_dir,
        runtime_dir / "audit_static_backend",
    )
    static_backend_rows = {
        row["requirement_id"]: row
        for row in static_backend_audit["capability_scorecard"]["rows"]
    }
    assert (
        static_backend_audit[
            "n_attached_formalizer_prior_feedback_lean_lsp_mcp_tool_calls"
        ]
        == 0
    )
    assert static_backend_rows[
        "formalizer_live_prover_tool_component_calibration"
    ]["passed"] is False
    assert rows["live_lean_lsp_mcp_called"]["passed"] is False
    assert (
        rows["formalizer_lean_candidate_proof_state_request_routed"]["passed"]
        is False
    )


