    assert row["source_theorem_ready_for_exact_proof_body"] is False
    assert row["source_theorem_semantic_support_only"] is True
    assert row["semantic_closure_status"] == (
        "REGISTERED_SUPPORT_VERIFIED_PLACEHOLDER_DEFINITION_OPEN"
    )
    assert row["placeholder_definition_status"] == (
        "OPEN_REQUIRES_REVIEWED_FORMAL_DEFINITION"
    )
    assert row["search_targets"] == [
        "exchangeable finite family",
        "StatInference conformal exchangeability primitive",
    ]

    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    problem = ProblemFormalizer().formalize(question)
    _procedures, theorem_goals = TheoryPlanner().plan(problem)
    catalog = FormalSubclaimProver().proof_obligation_catalog(problem, theorem_goals)
    summary = _formalizer_proof_bank_runtime_memory_summary(
        context={"runtime_learning_memory": memory},
        proof_bank_obligation_catalog=catalog,
        theorem_goals=theorem_goals,
        memory_kernel_verified_proof_obligation_ids=(),
        memory_prioritized_proof_obligation_ids=(),
    )
    prompt = build_formalizer_prompt(
        question=question,
        theory_packet={"packet_id": "theory:test", "formalization_requests": []},
        simulation_manifest={"manifest_id": "simulation:test", "simulation_passed": True},
        algorithm_manifest={"manifest_id": "algorithm:test", "n_executed": 1},
        registered_problem={"problem_class": problem.problem_class},
        theorem_goals=[
            {
                "id": theorem_goal.id,
                "title": theorem_goal.title,
                "proof_obligations": list(theorem_goal.proof_obligations),
            }
            for theorem_goal in theorem_goals
        ],
        proof_bank_obligation_catalog=catalog,
        proof_bank_runtime_memory_summary=summary,
    )

    assert summary["source_theorem_exact_candidate_requires_repair"] is True
    assert summary["source_theorem_exact_candidate_environment_gap"] is True
    assert summary["source_theorem_exact_candidate_repair_triggers"] == [
        "EXACT_SOURCE_SEMANTIC_DEFINITION_WORK_ORDER"
    ]
    assert summary["source_theorem_exact_candidate_placeholder_resolution_plan"][
        0
    ]["placeholder_symbol"] == "Exchangeable"
    assert "reviewed exchangeability predicate" in prompt
    assert "EXACT_SOURCE_SEMANTIC_DEFINITION_WORK_ORDER" in prompt

    converted_learning_path = tmp_path / "runtime_learning_rows.jsonl"
    converted_learning_rows = (
        _runtime_source_theorem_exact_semantic_definition_learning_rows(
            [json.loads(learning_path.read_text(encoding="utf-8").strip())]
        )
    )
    converted_learning_path.write_text(
        "\n".join(json.dumps(row) for row in converted_learning_rows) + "\n",
        encoding="utf-8",
    )
    converted_memory = _load_runtime_learning_memory([converted_learning_path])
    converted_summary = _formalizer_proof_bank_runtime_memory_summary(
        context={"runtime_learning_memory": converted_memory},
        proof_bank_obligation_catalog=catalog,
        theorem_goals=theorem_goals,
        memory_kernel_verified_proof_obligation_ids=(),
        memory_prioritized_proof_obligation_ids=(),
    )
    assert converted_memory["rows"][0]["learning_task"] == (
        "source_theorem_exact_semantic_definition_work_order"
    )
    assert converted_summary["source_theorem_exact_candidate_requires_repair"] is True
    assert converted_summary["source_theorem_exact_candidate_repair_triggers"] == [
        "EXACT_SOURCE_SEMANTIC_DEFINITION_WORK_ORDER"
    ]


