    placeholder_symbols = {
        row["placeholder_symbol"]
        for row in summary["source_theorem_exact_candidate_placeholder_resolution_plan"]
    }
    assert {"Exchangeable", "orderStatistic"} <= placeholder_symbols
    duplicate_rows = _append_runtime_generated_next_action_rows(
        agenda_rows,
        [post_executor_by_symbol["Exchangeable"]],
        queue_name=(
            "source_theorem_semantic_primitives_from_post_executor_"
            "formal_environment_proof_body_executor"
        ),
    )
    assert duplicate_rows == []
    assert len(agenda_rows) == 3


