def test_formalizer_validator_rejects_uninstantiated_adapter_object_binders() -> None:
    packet = {
        "formal_targets": [
            {
                "id": "split_conformal_hGoodCovered_repair",
                "informal_source": "derive hGoodCovered from source hypotheses",
                "lean_statement_sketch": (
                    "theorem split_conformal_hGoodCovered_repair "
                    "(covered : Set Nat) : covered ⊆ covered := by\n"
                    "  intro x hx\n"
                    "  exact hx"
                ),
                "expected_status": "NEEDS_KERNEL_CHECK",
            }
        ],
        "lemma_dependency_plan": [
            {
                "from": "exact source hypotheses",
                "to": "hGoodCovered",
                "role": "source-to-bridge premise derivation",
                "risk": "semantic alignment",
            }
        ],
        "retrieval_queries": [
            {
                "query": "split conformal instantiate covered rank BadRanks from hq hC",
                "target_library": "StatInference",
                "purpose": "premise derivation",
            }
        ],
        "proof_search_plan": {
            "preferred_tools": ["local Lean"],
            "kernel_check_plan": ["run local Lean on premise candidate"],
            "known_blockers": [],
        },
        "proof_bank_obligation_requests": [],
        "source_to_bridge_premise_derivation_candidates": [
            {
                "premise_name": "hGoodCovered",
                "target_theorem_name": "split_conformal_coverage",
                "target_lean_declaration": "split_conformal_coverage",
                "required_semantic_anchor_reference_names": ["hq", "hC"],
                "adapter_object_names_requiring_source_instantiation": [
                    "covered",
                    "rank",
                    "BadRanks",
                ],
                "premise_derivation_candidate_lean_source": (
                    "theorem split_conformal_coverage_hGoodCovered_source_to_bridge_derivation "
                    "(hq hC : Prop) "
                    "(covered : Set Nat) "
                    "(rank : Nat → Nat) "
                    "(BadRanks : Set Nat) : covered ⊆ covered := by\n"
                    "  intro x hx\n"
                    "  have hanchor : hq ∧ hC := And.intro hq hC\n"
                    "  exact hx\n"
                ),
            }
        ],
        "gap_taxonomy": [
            {"gap": "premise derivation still unproved", "kind": "semantic_alignment"}
        ],
        "critic_findings": [
            {
                "critic": "validator",
                "finding": "adapter objects must be source-instantiated",
            }
        ],
        "next_actions": [
            {
                "owner_agent": "ProofEngineer",
                "action": "replace adapter-object-parameterized candidate",
            }
        ],
        "proof_evidence_status": "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE",
        "kernel_verified": False,
        "full_frontier_theorem_proved": False,
    }

    errors = validate_formalizer_packet(packet)

    assert any("takes adapter objects as theorem binders" in error for error in errors)
    assert any(
        "covered" in error and "rank" in error and "BadRanks" in error
        for error in errors
    )


