    source_lookup_calls: list[dict[str, object]] = []

    def fake_source_lookup(
        *,
        out_dir: Path,
        queue_jsonl: Path | None = None,
        runtime_dir: Path | None = None,
        source_roots: list[Path] | None = None,
        max_hits_per_work_order: int = 8,
    ) -> dict[str, object]:
        assert runtime_dir is None
        assert queue_jsonl is not None and queue_jsonl.exists()
        queue_rows = [
            json.loads(line)
            for line in queue_jsonl.read_text(encoding="utf-8").splitlines()
            if line.strip()
        ]
        out_dir.mkdir(parents=True, exist_ok=True)
        lookup_rows_path = (
            out_dir
            / "source_theorem_exact_semantic_definition_source_lookup_rows.jsonl"
        )
        review_packets_path = (
            out_dir
            / "source_theorem_exact_semantic_definition_closure_review_packets.jsonl"
        )
        learning_path = out_dir / "runtime_learning_rows.jsonl"
        manifest_path = (
            out_dir
            / "source_theorem_exact_semantic_definition_source_lookup_manifest.json"
        )
        lookup_rows = [
            {
                "schema_version": 1,
                "artifact_kind": (
                    "RuntimeSourceTheoremExactSemanticDefinitionSourceLookupRow"
                ),
                "lookup_id": f"source_lookup:{row.get('placeholder_symbol', '')}",
                "source_work_order_id": row.get("work_order_id", ""),
                "target_theorem_name": row.get("target_theorem_name", ""),
                "placeholder_symbol": row.get("placeholder_symbol", ""),
                "lookup_status": "NO_SOURCE_DECLARATIONS_FOUND",
                "source_lookup_hits": [],
                "proof_evidence_status": "SOURCE_LOOKUP_NOT_PROOF_EVIDENCE",
            }
            for row in queue_rows
        ]
        review_packets = [
            {
                "schema_version": 1,
                "artifact_kind": (
                    "RuntimeSourceTheoremExactSemanticDefinitionClosureReviewPacket"
                ),
                "review_packet_id": f"review:{row.get('placeholder_symbol', '')}",
                "source_work_order_id": row.get("work_order_id", ""),
                "target_theorem_name": row.get("target_theorem_name", ""),
                "placeholder_symbol": row.get("placeholder_symbol", ""),
                "candidate_source_declarations": [],
                "definition_contract": {
                    "replacement_strategy": row.get("replacement_strategy", ""),
                    "placeholder_symbol": row.get("placeholder_symbol", ""),
                },
                "proof_evidence_status": (
                    "DEFINITION_CLOSURE_REVIEW_PACKET_NOT_PROOF_EVIDENCE"
                ),
            }
            for row in queue_rows
        ]
        learning_rows = [
            {
                "schema_version": 1,
                "artifact_kind": (
                    "RuntimeSourceTheoremExactSemanticDefinitionSourceLookupRow"
                ),
                "learning_task": (
                    "source_theorem_exact_semantic_definition_source_lookup"
                ),
                "target_theorem_name": row.get("target_theorem_name", ""),
                "work_order_id": row.get("work_order_id", ""),
                "placeholder_symbol": row.get("placeholder_symbol", ""),
                "lookup_status": "NO_SOURCE_DECLARATIONS_FOUND",
                "input_summary": {
                    "trigger": "EXACT_SOURCE_SEMANTIC_DEFINITION_SOURCE_LOOKUP",
                    "placeholder_symbol": row.get("placeholder_symbol", ""),
                },
                "proof_evidence_status": "SOURCE_LOOKUP_NOT_PROOF_EVIDENCE",
            }
            for row in queue_rows
        ]
        lookup_rows_path.write_text(
            "\n".join(json.dumps(row) for row in lookup_rows) + "\n",
            encoding="utf-8",
        )
        review_packets_path.write_text(
            "\n".join(json.dumps(row) for row in review_packets) + "\n",
            encoding="utf-8",
        )
        learning_path.write_text(
            "\n".join(json.dumps(row) for row in learning_rows) + "\n",
            encoding="utf-8",
        )
        manifest = {
            "schema_version": 1,
            "artifact_kind": (
                "RuntimeSourceTheoremExactSemanticDefinitionSourceLookupManifest"
            ),
            "manifest_path": str(manifest_path),
            "source_work_orders_jsonl": str(queue_jsonl),
            "lookup_rows_jsonl": str(lookup_rows_path),
            "definition_closure_review_packets_jsonl": str(review_packets_path),
            "runtime_learning_rows_jsonl": str(learning_path),
            "n_work_orders": len(queue_rows),
            "n_lookup_rows": len(lookup_rows),
            "n_definition_closure_review_packets": len(review_packets),
            "n_runtime_learning_rows": len(learning_rows),
            "n_source_lookup_hits": 0,
            "proof_evidence_status": "SOURCE_LOOKUP_NOT_PROOF_EVIDENCE",
        }
        manifest_path.write_text(json.dumps(manifest), encoding="utf-8")
        source_lookup_calls.append(
            {
                "out_dir": str(out_dir),
                "queue_jsonl": str(queue_jsonl),
                "queue_rows": queue_rows,
                "source_roots": [str(root) for root in source_roots or []],
                "max_hits_per_work_order": max_hits_per_work_order,
            }
        )
        return manifest

