def test_source_theorem_kernel_evidence_registries_separate_raw_and_audit_counts() -> None:
    raw_keys = set(SOURCE_THEOREM_RAW_KERNEL_EVIDENCE_COUNT_KEYS)
    audit_keys = set(SOURCE_THEOREM_AUDIT_KERNEL_EVIDENCE_COUNT_KEYS)
    target_bound_keys = set(SOURCE_THEOREM_TARGET_BOUND_KERNEL_EVIDENCE_COUNT_KEYS)
    target_bound_target_keys = set(
        SOURCE_THEOREM_TARGET_BOUND_KERNEL_EVIDENCE_TARGET_KEYS
    )
    full_frontier_target_bound_keys = set(
        FULL_FRONTIER_TARGET_BOUND_KERNEL_EVIDENCE_COUNT_KEYS
    )
    full_frontier_target_bound_target_keys = set(
        FULL_FRONTIER_TARGET_BOUND_KERNEL_EVIDENCE_TARGET_KEYS
    )
    aggregate_kernel_keys = set(
        SOURCE_THEOREM_AUDIT_FORMAL_ENV_AGGREGATE_KERNEL_EVIDENCE_KEYS
    )
    aggregate_result_keys = set(
        SOURCE_THEOREM_AUDIT_FORMAL_ENV_AGGREGATE_RESULT_ROW_KEYS
    )

    assert audit_keys < raw_keys
    assert aggregate_kernel_keys < raw_keys
    assert len(SOURCE_THEOREM_AUDIT_FORMAL_ENV_AGGREGATE_KERNEL_EVIDENCE_KEYS) == len(
        SOURCE_THEOREM_AUDIT_FORMAL_ENV_AGGREGATE_RESULT_ROW_KEYS
    )
    assert all(key.endswith("_n_source_theorem_kernel_verified") for key in aggregate_kernel_keys)
    assert all(key.endswith("_n_result_rows") for key in aggregate_result_keys)
    assert (
        "source_theorem_formal_environment_proof_body_executor_n_source_theorem_kernel_verified"
        in audit_keys
    )
    assert (
        "source_theorem_exact_proof_body_repair_executor_n_source_theorem_kernel_verified"
        in raw_keys
    )
    assert (
        "source_theorem_exact_proof_body_repair_executor_n_source_theorem_kernel_verified"
        not in audit_keys
    )
    assert (
        "source_theorem_exact_semantic_definition_proof_body_recheck_executor_n_source_theorem_kernel_verified"
        in raw_keys
    )
    assert (
        "source_theorem_exact_semantic_definition_proof_body_recheck_executor_n_source_theorem_kernel_verified"
        in audit_keys
    )
    assert (
        "source_theorem_formal_environment_proof_body_executor_from_source_semantic_promotion_n_source_theorem_kernel_verified"
        in raw_keys
    )
    assert (
        "source_theorem_formal_environment_proof_body_executor_from_source_semantic_promotion_n_source_theorem_kernel_verified"
        not in audit_keys
    )
    assert (
        "source_theorem_formal_environment_proof_body_executor_from_source_semantic_promotion_n_source_theorem_kernel_verified"
        in aggregate_kernel_keys
    )
    assert (
        "source_theorem_exact_proof_body_repair_executor_from_adapter_premise_derivation_feedback_n_source_theorem_kernel_verified"
        in aggregate_kernel_keys
    )
    assert (
        "source_theorem_exact_semantic_definition_typechecked_review_proof_body_recheck_executor_n_source_theorem_kernel_verified"
        not in aggregate_kernel_keys
    )
    assert (
        "source_theorem_exact_semantic_definition_proof_body_recheck_executor_n_source_theorem_kernel_verified"
        not in aggregate_kernel_keys
    )
    assert (
        "source_theorem_promotion_post_executor_proofengineer_bridge_n_source_theorem_kernel_verified"
        in audit_keys
    )
    assert (
        "source_theorem_promotion_post_executor_proofengineer_bridge_n_source_theorem_kernel_verified"
        not in aggregate_kernel_keys
    )
    assert "n_source_theorem_target_bound_kernel_verified" in target_bound_keys
    assert "source_theorem_kernel_verified_target_ids" in target_bound_target_keys
    assert (
        "n_full_frontier_target_bound_kernel_verified"
        in full_frontier_target_bound_keys
    )
    assert (
        "full_frontier_theorem_kernel_verified_target_ids"
        in full_frontier_target_bound_target_keys
    )


def test_runtime_evidence_summary_requires_full_frontier_target_binding() -> None:
    artifacts = {
        "formalization_manifest:raw-full": {
            "artifact_kind": "RuntimeFormalizationManifest",
            "counts": {"proved": 1, "kernel_verified": 1, "formal_gap": 0},
            "formal_subclaims": [
                {
                    "id": "helper_lemma",
                    "status": "PROVED",
                    "kernel_verified": True,
                    "verifier": "local.lake_env_lean",
                    "proof_obligation_id": "helper_lemma",
                }
            ],
            "full_frontier_theorem_proved": True,
        }
    }

    evidence_summary = _runtime_evidence_summary(
        [{"blackboard": {"artifacts": artifacts}}]
    )
    proof = evidence_summary["proof"]
    scorecard = _runtime_capability_scorecard(
        {
            "n_full_frontier_theorem_proved": 1,
            "n_formal_gaps": 0,
        }
    )
    rows = {row["requirement_id"]: row for row in scorecard["rows"]}

    assert proof["n_full_frontier_raw_theorem_proved_claims"] == 1
    assert proof["n_full_frontier_target_bound_kernel_verified"] == 0
    assert proof["n_full_frontier_theorem_proved"] == 0
    assert rows["full_frontier_theorem_kernel_proved"]["passed"] is False
    assert "target_bound_full_frontier_kernel=0" in rows[
        "full_frontier_theorem_kernel_proved"
    ]["evidence"]


def test_runtime_capability_scorecard_recomputes_full_frontier_target_binding() -> None:
    payload = {
        "n_results": 2,
        "n_distinct_question_ids": 2,
        "question_ids": [
            "causal_ate_aipw",
            "conformal_prediction_coverage",
        ],
        "n_full_frontier_theorem_proved": 2,
        "n_full_frontier_target_bound_kernel_verified": 2,
        "question_ids_with_full_frontier_theorem_proved": [
            "causal_ate_aipw",
            "conformal_prediction_coverage",
        ],
        "n_question_ids_with_full_frontier_theorem_proved": 2,
        "task_families": ["causal", "conformal"],
        "n_distinct_task_families": 2,
        "task_families_with_full_frontier_theorem_proved": [
            "causal",
            "conformal",
        ],
        "n_task_families_with_full_frontier_theorem_proved": 2,
        "task_families_with_full_frontier_target_bound_kernel_verified": [
            "causal",
            "conformal",
        ],
        "n_task_families_with_full_frontier_target_bound_kernel_verified": 2,
        "n_formal_gaps": 0,
    }

    scorecard = _runtime_capability_scorecard(payload)
    rows = {row["requirement_id"]: row for row in scorecard["rows"]}
    ladder = _runtime_capability_ladder(payload)
    ladder_rows = {row["level"]: row for row in ladder["levels"]}

    assert rows["full_frontier_theorem_kernel_proved"]["passed"] is False
    assert rows[
        "cross_task_full_theorem_generalization_demonstrated"
    ]["passed"] is False
    assert ladder_rows[8]["passed"] is False
    assert ladder_rows[9]["passed"] is False
    assert "target_bound_full_frontier_kernel=0" in rows[
        "full_frontier_theorem_kernel_proved"
    ]["evidence"]

    payload.update(
        {
            "full_frontier_current_target_ids": [
                "causal_ate_aipw:main",
                "conformal_prediction_coverage:main",
            ],
            "full_frontier_theorem_kernel_verified_target_ids": [
                "causal_ate_aipw:main",
                "conformal_prediction_coverage:main",
            ],
            "full_frontier_kernel_verified_matching_target_ids": [
                "causal_ate_aipw:main",
                "conformal_prediction_coverage:main",
            ],
        }
    )
    scorecard = _runtime_capability_scorecard(payload)
    rows = {row["requirement_id"]: row for row in scorecard["rows"]}
    ladder = _runtime_capability_ladder(payload)
    ladder_rows = {row["level"]: row for row in ladder["levels"]}

    assert rows["full_frontier_theorem_kernel_proved"]["passed"] is True
    assert rows[
        "cross_task_full_theorem_generalization_demonstrated"
    ]["passed"] is True
    assert ladder_rows[8]["passed"] is True
    assert ladder_rows[9]["passed"] is True


