def test_runtime_audit_recomputes_stale_research_path_control(
    tmp_path: Path,
) -> None:
    runtime_dir = tmp_path / "runtime"
    runtime_dir.mkdir()
    result_path = runtime_dir / "causal_ate_aipw_runtime_result.json"
    traces_path = runtime_dir / "runtime_traces.jsonl"
    agenda_path = runtime_dir / "runtime_next_action_agenda.jsonl"
    learning_path = runtime_dir / "runtime_learning_rows.jsonl"
    result = {
        "status": "ACCEPTED",
        "blackboard": {
            "project_id": "ai_statistician:causal_ate_aipw",
            "artifacts": {
                "retrieval:historical": {
                    "artifact_kind": "RuntimeRetrievalMemoryManifest",
                    "evidence_contract": {
                        "formal_verification_policy": "optional",
                        "recommended_research_path": "dual_track",
                    },
                },
                "formalization:current": {
                    "artifact_kind": "RuntimeFormalizationManifest",
                    "runtime_architect_control": {
                        "subsystem": "ProofEngineer",
                        "evidence_contract": {
                            "formal_verification_policy": "required",
                            "recommended_research_path": "proof_first",
                            "formal_required_for_final": True,
                        },
                    },
                },
            },
        },
        "traces": [
            {
                "subsystem": "ProofEngineer",
                "produced_artifact_ids": ["formalization:current"],
            }
        ],
    }
    result_path.write_text(json.dumps(result, sort_keys=True), encoding="utf-8")
    traces_path.write_text(
        json.dumps({"subsystem": "ProofEngineer"}) + "\n",
        encoding="utf-8",
    )
    agenda_path.write_text("", encoding="utf-8")
    learning_path.write_text("", encoding="utf-8")
    manifest = {
        "schema_version": 1,
        "runtime_stage": (
            "architect_retrieval_theory_simulation_algorithm_formalization_"
            "critic_environment_loop"
        ),
        "runtime_evaluation_mode": "capability_eval",
        "formal_verification_policy": "required",
        "requested_formal_verification_policy": "required",
        "effective_formal_verification_policy": "required",
        "effective_recommended_research_path": "dual_track",
        "architect_recommended_formal_verification_policy": "optional",
        "architect_recommended_research_path": "dual_track",
        "runtime_research_path_control_propagated": False,
        "runtime_research_path_execution_summary": {
            "n_controlled_artifacts": 2,
            "n_controlled_artifacts_with_evidence_contract": 1,
            "n_policy_mismatches": 1,
            "n_path_mismatches": 1,
            "path_control_propagated": False,
        },
        "n_questions": 1,
        "n_runtime_next_action_items": 0,
        "n_runtime_learning_rows": 0,
        "artifacts": {
            "per_question_results": [str(result_path)],
            "runtime_traces_jsonl": str(traces_path),
            "runtime_next_action_agenda_jsonl": str(agenda_path),
            "runtime_learning_rows_jsonl": str(learning_path),
        },
    }
    (runtime_dir / "research_agent_runtime_manifest.json").write_text(
        json.dumps(manifest, sort_keys=True),
        encoding="utf-8",
    )

    audit = audit_research_agent_runtime(runtime_dir, runtime_dir / "audit")

    assert audit["runtime_research_path_execution_summary_source"] == (
        "result_artifacts_recomputed"
    )
    assert audit["runtime_research_path_manifest_stale"] is True
    assert audit["architect_recommended_formal_verification_policy"] == "required"
    assert audit["architect_recommended_research_path"] == "proof_first"
    assert audit["effective_recommended_research_path"] == "proof_first"
    assert audit["runtime_research_path_control_propagated"] is True
    summary = audit["runtime_research_path_execution_summary"]
    assert audit["n_runtime_current_artifacts_scanned_for_architect_control"] == 1
    assert audit["n_runtime_current_artifacts_missing_architect_control"] == 0
    assert audit["runtime_current_artifacts_missing_architect_control_ids"] == []
    assert audit["n_runtime_produced_artifact_ids_missing_from_blackboard"] == 0
    assert audit["runtime_produced_artifact_ids_missing_from_blackboard"] == []
    assert summary["n_current_artifacts"] == 1
    assert summary["n_controlled_artifacts"] == 1
    assert summary["n_historical_controlled_input_artifacts_skipped"] == 0
    assert summary["n_current_artifacts_missing_architect_control"] == 0
    assert summary["n_produced_artifact_ids_missing_from_blackboard"] == 0
    assert summary["n_policy_mismatches"] == 0
    assert summary["n_path_mismatches"] == 0


def test_runtime_capability_scorecard_requires_cross_task_theorem_generalization() -> None:
    payload = {
        "n_results": 1,
        "n_distinct_question_ids": 1,
        "question_ids": ["conformal_prediction_coverage"],
        "n_full_frontier_theorem_proved": 1,
        **_target_bound_full_frontier_payload(),
        "question_ids_with_full_frontier_theorem_proved": [
            "conformal_prediction_coverage"
        ],
        "n_question_ids_with_full_frontier_theorem_proved": 1,
        "task_families": ["conformal"],
        "n_distinct_task_families": 1,
        "task_families_with_full_frontier_theorem_proved": ["conformal"],
        "n_task_families_with_full_frontier_theorem_proved": 1,
    }

    scorecard = _runtime_capability_scorecard(payload)
    rows = {row["requirement_id"]: row for row in scorecard["rows"]}

    assert rows["full_frontier_theorem_kernel_proved"]["passed"] is True
    assert rows[
        "cross_task_full_theorem_generalization_demonstrated"
    ]["passed"] is False
    cross_task_row = rows["cross_task_full_theorem_generalization_demonstrated"]
    assert "two question ids inside one family" in rows[
        "cross_task_full_theorem_generalization_demonstrated"
    ]["blocker"]
    assert cross_task_row["next_owner_subsystem"] == "ArchitectCoordinator"
    assert "--question-task-family conformal" in cross_task_row[
        "recommended_capability_eval_command"
    ]
    assert "--question-task-family experimental_design" in cross_task_row[
        "recommended_capability_eval_command"
    ]
    assert "--min-task-families 2" in cross_task_row[
        "recommended_capability_eval_command"
    ]
    assert cross_task_row["proof_evidence_status"] == (
        "CAPABILITY_SCORECARD_ROUTING_NOT_PROOF_EVIDENCE"
    )

    legacy_question_only_payload = {
        "n_results": 2,
        "n_distinct_question_ids": 2,
        "question_ids": [
            "causal_ate_aipw",
            "conformal_prediction_coverage",
        ],
        "n_full_frontier_theorem_proved": 2,
        "question_ids_with_full_frontier_theorem_proved": [
            "causal_ate_aipw",
            "conformal_prediction_coverage",
        ],
        "n_question_ids_with_full_frontier_theorem_proved": 2,
    }
    scorecard = _runtime_capability_scorecard(legacy_question_only_payload)
    rows = {row["requirement_id"]: row for row in scorecard["rows"]}
    ladder = _runtime_capability_ladder(legacy_question_only_payload)
    ladder_rows = {row["level"]: row for row in ladder["levels"]}

    assert rows[
        "cross_task_full_theorem_generalization_demonstrated"
    ]["passed"] is False
    assert rows["full_frontier_theorem_kernel_proved"]["passed"] is False
    assert ladder_rows[9]["passed"] is False

    non_evidence_family_payload = {
        **legacy_question_only_payload,
        "task_families": ["unclassified", "question_id:legacy"],
        "n_distinct_task_families": 2,
        "task_families_with_full_frontier_theorem_proved": [
            "unclassified",
            "question_id:legacy",
        ],
        "n_task_families_with_full_frontier_theorem_proved": 2,
    }
    scorecard = _runtime_capability_scorecard(non_evidence_family_payload)
    rows = {row["requirement_id"]: row for row in scorecard["rows"]}
    ladder = _runtime_capability_ladder(non_evidence_family_payload)
    ladder_rows = {row["level"]: row for row in ladder["levels"]}

    assert rows[
        "cross_task_full_theorem_generalization_demonstrated"
    ]["passed"] is False
    assert ladder_rows[9]["passed"] is False

    payload["n_results"] = 2
    payload["n_distinct_question_ids"] = 2
    payload["question_ids"] = [
        "causal_ate_aipw",
        "conformal_prediction_coverage",
    ]
    payload["n_full_frontier_theorem_proved"] = 2
    payload.update(_target_bound_full_frontier_payload(count=2))
    payload["question_ids_with_full_frontier_theorem_proved"] = [
        "causal_ate_aipw",
        "conformal_prediction_coverage",
    ]
    payload["n_question_ids_with_full_frontier_theorem_proved"] = 2
    payload["task_families"] = ["conformal"]
    payload["n_distinct_task_families"] = 1
    payload["task_families_with_full_frontier_theorem_proved"] = ["conformal"]
    payload["n_task_families_with_full_frontier_theorem_proved"] = 1
    scorecard = _runtime_capability_scorecard(payload)
    rows = {row["requirement_id"]: row for row in scorecard["rows"]}
    ladder = _runtime_capability_ladder(payload)
    ladder_rows = {row["level"]: row for row in ladder["levels"]}

    assert rows[
        "cross_task_full_theorem_generalization_demonstrated"
    ]["passed"] is False
    assert ladder_rows[9]["passed"] is False

    payload["task_families"] = ["causal", "conformal"]
    payload["n_distinct_task_families"] = 2
    payload["task_families_with_full_frontier_theorem_proved"] = [
        "causal",
        "conformal",
    ]
    payload["n_task_families_with_full_frontier_theorem_proved"] = 2
    payload["n_task_families_with_full_frontier_target_bound_kernel_verified"] = 2
    scorecard = _runtime_capability_scorecard(payload)
    rows = {row["requirement_id"]: row for row in scorecard["rows"]}
    ladder = _runtime_capability_ladder(payload)
    ladder_rows = {row["level"]: row for row in ladder["levels"]}

    assert rows[
        "cross_task_full_theorem_generalization_demonstrated"
    ]["passed"] is False
    assert "task_families_with_full_frontier_target_bound_kernel_verified=None" in rows[
        "cross_task_full_theorem_generalization_demonstrated"
    ]["evidence"]
    assert ladder_rows[9]["passed"] is False

    payload["task_families_with_full_frontier_target_bound_kernel_verified"] = [
        "causal",
        "conformal",
    ]
    scorecard = _runtime_capability_scorecard(payload)
    rows = {row["requirement_id"]: row for row in scorecard["rows"]}
    ladder = _runtime_capability_ladder(payload)
    ladder_rows = {row["level"]: row for row in ladder["levels"]}

    assert rows[
        "cross_task_full_theorem_generalization_demonstrated"
    ]["passed"] is True
    assert "recommended_capability_eval_command" not in rows[
        "cross_task_full_theorem_generalization_demonstrated"
    ]
    assert ladder["scale"] == "L0-L9"
    assert ladder_rows[9]["passed"] is True


def test_runtime_audit_l9_uses_recovered_task_family_not_only_question_id(
    tmp_path: Path,
) -> None:
    runtime_dir = tmp_path / "runtime"
    runtime_dir.mkdir()
    traces = runtime_dir / "runtime_traces.jsonl"
    agenda = runtime_dir / "runtime_next_action_agenda.jsonl"
    learning = runtime_dir / "runtime_learning_rows.jsonl"
    traces.write_text("", encoding="utf-8")
    agenda.write_text("", encoding="utf-8")
    learning.write_text("", encoding="utf-8")

    result_paths = []
    for question_id in (
        "conformal_prediction_coverage",
        "conformal_selection_width",
    ):
        result_path = runtime_dir / f"{question_id}_runtime_result.json"
        result_path.write_text(
            json.dumps(
                {
                    "status": "ACCEPTED",
                    "final_task_id": "critic:done",
                    "blackboard": {
                        "project_id": f"ai_statistician:{question_id}",
                        "artifacts": {
                            f"runtime_question_metadata:{question_id}": {
                                "artifact_kind": "RuntimeQuestionMetadata",
                                "primary_task_family": "conformal",
                                "question": {
                                    "id": question_id,
                                    "title": question_id,
                                    "description": "",
                                    "tags": ["conformal", "coverage"],
                                },
                            },
                            f"formalization_manifest:{question_id}": {
                                "counts": {
                                    "kernel_verified": 1,
                                    "formal_gap": 0,
                                },
                                "formal_subclaims": [
                                    {
                                        "id": f"{question_id}:source",
                                        "kernel_verified": True,
                                        "verifier": "local.lake_env_lean",
                                    }
                                ],
                                "full_frontier_current_target_ids": [
                                    f"{question_id}:source"
                                ],
                                "full_frontier_theorem_kernel_verified_target_ids": [
                                    f"{question_id}:source"
                                ],
                                "n_full_frontier_target_bound_kernel_verified": 1,
                                "full_frontier_theorem_proved": True,
                            },
                        },
                    },
                    "traces": [],
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )
        result_paths.append(str(result_path))

    (runtime_dir / "research_agent_runtime_manifest.json").write_text(
        json.dumps(
            {
                "schema_version": 1,
                "runtime_stage": (
                    "architect_retrieval_theory_simulation_algorithm_"
                    "formalization_critic_environment_loop"
                ),
                "n_questions": 2,
                "n_runtime_next_action_items": 0,
                "n_runtime_learning_rows": 0,
                "artifacts": {
                    "per_question_results": result_paths,
                    "runtime_traces_jsonl": str(traces),
                    "runtime_next_action_agenda_jsonl": str(agenda),
                    "runtime_learning_rows_jsonl": str(learning),
                },
            },
            sort_keys=True,
        ),
        encoding="utf-8",
    )

    audit = audit_research_agent_runtime(runtime_dir, runtime_dir / "audit")
    scorecard_rows = {
        row["requirement_id"]: row for row in audit["capability_scorecard"]["rows"]
    }
    ladder_rows = {row["level"]: row for row in audit["capability_ladder"]["levels"]}

    assert audit["n_full_frontier_theorem_proved"] == 2
    assert audit["n_full_frontier_target_bound_kernel_verified"] == 2
    assert audit["full_frontier_kernel_verified_matching_target_ids"] == [
        "conformal_prediction_coverage:source",
        "conformal_selection_width:source",
    ]
    assert audit["n_distinct_question_ids"] == 2
    assert audit["task_families"] == ["conformal"]
    assert audit["n_distinct_task_families"] == 1
    assert audit["task_families_with_full_frontier_theorem_proved"] == [
        "conformal"
    ]
    assert scorecard_rows[
        "cross_task_full_theorem_generalization_demonstrated"
    ]["passed"] is False
    report = (runtime_dir / "audit" / "research_agent_runtime_audit.md").read_text(
        encoding="utf-8"
    )
    assert "## Capability Routing" in report
    assert "--question-task-family conformal" in report
    assert "--question-task-family experimental_design" in report
    assert "evaluation routing metadata" in report
    assert ladder_rows[9]["passed"] is False


