def test_local_lean_proof_state_provider_requests_search_and_multi_attempt_on_failure() -> None:
    provider = LocalLeanProofStateFeedbackProvider(lean_command=("false",))
    rows = provider.inspect(
        [
            FormalSubclaim(
                id="bad_candidate",
                title="bad candidate",
                status="FAILED",
                claim="bad local Lean candidate",
                lean_statement="theorem bad_candidate : True := by\n  trivial\n",
                errors=["local Lean failed"],
            )
        ]
    )

    assert len(rows) == 1
    row = rows[0]
    assert row.attempt_status == "local_lean_failed"
    assert row.local_lean_checked is True
    assert row.local_lean_returncode == 1
    assert set(row.provider_preferences) >= {
        "lean_lsp_mcp",
        "openprover_or_reprover_premise_search",
        "local_lean_proof_state_adapter",
    }
    assert set(row.requested_tools) >= {
        "lean_diagnostic_messages",
        "lean_goal",
        "lean_state_search",
        "proof_search",
        "lean_multi_attempt",
        "local_lean_or_axle_rerun",
    }
    assert row.executed_tools == ("local.lake_env_lean", "lean_diagnostic_messages")
    assert row.tool_call_trace
    assert row.tool_call_trace[0]["tool"] == "local.lake_env_lean"
    assert row.tool_call_trace[0]["status"] == "local_lean_failed"
    assert row.tool_call_trace[0]["proof_evidence_status"] == (
        PROOF_STATE_FEEDBACK_STATUS
    )
    assert row.route_revision_recommended is True
    assert row.proof_evidence_status == PROOF_STATE_FEEDBACK_STATUS


