def test_local_lean_proof_state_provider_skips_implicit_mathlib_when_root_missing(
    tmp_path: Path,
) -> None:
    captured_source = tmp_path / "captured.lean"
    fake_lean = tmp_path / "fake_lean.py"
    fake_lean.write_text(
        "\n".join(
            [
                "from pathlib import Path",
                "import sys",
                f"Path({str(captured_source)!r}).write_text(",
                "    Path(sys.argv[-1]).read_text(encoding='utf-8'),",
                "    encoding='utf-8',",
                ")",
                "print('fake local Lean failed')",
                "raise SystemExit(1)",
            ]
        ),
        encoding="utf-8",
    )
    provider = LocalLeanProofStateFeedbackProvider(
        project_root=tmp_path,
        lean_command=(sys.executable, str(fake_lean)),
    )

    row = provider.inspect(
        [
            FormalSubclaim(
                id="no_import_candidate",
                title="no import candidate",
                status="FAILED",
                claim="no import local Lean candidate",
                lean_statement="theorem no_import_candidate : True := by\n  trivial\n",
                errors=["local Lean failed"],
            )
        ]
    )[0]

    source = captured_source.read_text(encoding="utf-8")
    assert not source.lstrip().startswith("import Mathlib")
    assert "theorem no_import_candidate" in source
    assert any(
        "implicit `import Mathlib` skipped" in diagnostic
        for diagnostic in row.diagnostics
    )
    assert row.attempt_status == "local_lean_failed"
    assert row.local_lean_checked is True


def test_lean_lsp_mcp_proof_state_provider_records_live_tool_trace(tmp_path: Path) -> None:
    (tmp_path / "lean-toolchain").write_text("leanprover/lean4:v4.14.0\n", encoding="utf-8")
    artifact = tmp_path / "Candidate.lean"
    artifact.write_text("theorem candidate : True := by\n  trivial\n", encoding="utf-8")
    fake_mcp = tmp_path / "fake_mcp.py"
    fake_mcp.write_text(
        "\n".join(
            [
                "import json, sys",
                "for line in sys.stdin:",
                "    msg = json.loads(line)",
                "    if msg.get('method') == 'initialize':",
                "        print(json.dumps({'jsonrpc':'2.0','id':msg['id'],'result':{'protocolVersion':'2025-03-26','capabilities':{},'serverInfo':{'name':'fake','version':'0'}}}), flush=True)",
                "    elif msg.get('method') == 'tools/call':",
                "        print(json.dumps({'jsonrpc':'2.0','id':msg['id'],'result':{'content':[{'type':'text','text':'fake Lean LSP diagnostics: no goals'}]}}), flush=True)",
            ]
        ),
        encoding="utf-8",
    )
    provider = LeanLspMcpProofStateFeedbackProvider(
        project_root=tmp_path,
        lean_command=("false",),
        mcp_command=(sys.executable, str(fake_mcp)),
        mcp_timeout_s=5,
    )

    rows = provider.inspect(
        [
            FormalSubclaim(
                id="candidate",
                title="candidate",
                status="FAILED",
                claim="candidate",
                lean_statement=artifact.read_text(encoding="utf-8"),
                artifact_path=str(artifact),
            )
        ]
    )

    assert len(rows) == 1
    row = rows[0]
    assert row.provider_name == "lean_lsp_mcp_proof_state_feedback"
    assert row.artifact_path == str(artifact)
    assert "local.lake_env_lean" in row.executed_tools
    assert "lean_lsp_mcp.lean_diagnostic_messages" in row.executed_tools
    assert "lean_lsp_mcp.lean_goal" in row.executed_tools
    assert "lean_lsp_mcp.lean_state_search" in row.executed_tools
    assert {
        trace.get("tool")
        for trace in row.tool_call_trace
        if str(trace.get("tool", "")).startswith("lean_lsp_mcp.")
    } == {
        "lean_lsp_mcp.lean_diagnostic_messages",
        "lean_lsp_mcp.lean_goal",
        "lean_lsp_mcp.lean_state_search",
    }
    assert all(
        trace["status"] == "mcp_tool_call_succeeded"
        for trace in row.tool_call_trace
        if str(trace.get("tool", "")).startswith("lean_lsp_mcp.")
    )
    assert any(
        "fake Lean LSP diagnostics" in str(trace.get("diagnostics_excerpt", ""))
        for trace in row.tool_call_trace
    )
    assert row.proof_evidence_status == PROOF_STATE_FEEDBACK_STATUS


def test_lean_lsp_mcp_missing_artifact_records_skipped_trace() -> None:
    provider = LeanLspMcpProofStateFeedbackProvider(
        lean_command=("false",),
        mcp_command=(sys.executable, "-c", "raise SystemExit(1)"),
        mcp_timeout_s=1,
    )

    row = provider.inspect(
        [
            FormalSubclaim(
                id="candidate_without_artifact",
                title="candidate without artifact",
                status="FAILED",
                claim="candidate",
                lean_statement=(
                    "theorem candidate_without_artifact : True := by\n"
                    "  trivial\n"
                ),
            )
        ]
    )[0]

    assert row.provider_name == "lean_lsp_mcp_proof_state_feedback"
    assert row.artifact_path == ""
    assert row.tool_call_trace[-1]["tool"] == (
        "lean_lsp_mcp.lean_diagnostic_messages"
    )
    assert row.tool_call_trace[-1]["status"] == (
        "mcp_tool_call_skipped_no_artifact"
    )
    assert not any(
        str(tool).startswith("lean_lsp_mcp.") for tool in row.executed_tools
    )
    assert "local.lake_env_lean" in row.executed_tools
    assert any(
        "no materialized artifact_path" in diagnostic
        for diagnostic in row.diagnostics
    )


