def test_research_agent_runtime_cli_resumes_from_pending_task_manifest() -> None:
    root = Path("runs/test_research_agent_runtime_cli_resume")
    shutil.rmtree(root, ignore_errors=True)
    root.mkdir(parents=True, exist_ok=True)
    response_file = root / "response.json"
    architect_response_file = root / "architect_response.json"
    resume_manifest = root / "prior_manifest.json"
    out_dir = root / "out"
    response_file.write_text(json.dumps(_runtime_sample_response()), encoding="utf-8")
    architect_response_file.write_text(
        json.dumps(_architect_sample_response()),
        encoding="utf-8",
    )
    question = load_open_research_questions(Path("examples/research_questions.json"))[0]
    question_payload = {
        "id": question.id,
        "title": question.title,
        "description": question.description,
        "tags": list(question.tags),
    }
    resume_task = {
        "task_id": "theory-critic-revise:causal_ate_aipw:test",
        "owner_subsystem": "TheoryDeveloper",
        "objective": "Revise the theory packet from critic feedback.",
        "inputs": {
            "question": question_payload,
            "environment_feedback": {
                "feedback_source": "CriticEvaluator",
                "required_revision": "address the exact formal gap before rerouting",
            },
        },
        "allowed_tools": ["model_backend", "rag_memory", "evidence_ledger"],
        "budget": {},
        "expected_artifacts": ["critic_revised_theory_derivation_packet"],
        "acceptance_gate": "revised packet addresses critic feedback",
        "stop_condition": "reroute through simulation and formalization gates",
    }
    resume_manifest.write_text(
        json.dumps(
            {
                "schema_version": 1,
                "question_ids": ["causal_ate_aipw"],
                "runtime_failure_summary": {
                    "terminal_question_id": "causal_ate_aipw",
                    "pending_next_task_id": resume_task["task_id"],
                },
                "incomplete_pending_next_task_id": resume_task["task_id"],
                "incomplete_pending_next_task": resume_task,
            }
        ),
        encoding="utf-8",
    )

    code = main(
        [
            "research-agent-runtime",
            "--provider",
            "static",
            "--static-response-file",
            str(response_file),
            "--architect-coordinator-provider",
            "none",
            "--simulation-engineer-provider",
            "none",
            "--algorithm-engineer-provider",
            "none",
            "--formalizer-provider",
            "none",
            "--critic-evaluator-provider",
            "none",
            "--question-file",
            "examples/research_questions.json",
            "--resume-runtime-manifest",
            str(resume_manifest),
            "--max-iterations",
            "1",
            "--out",
            str(out_dir),
        ]
    )

    assert code == 0
    manifest = json.loads((out_dir / "research_agent_runtime_manifest.json").read_text())
    assert manifest["question_ids"] == ["causal_ate_aipw"]
    assert manifest["runtime_resumed_from_pending_task"] is True
    assert manifest["runtime_resume_policy"] == "direct_pending_task"
    assert manifest["runtime_resume_context"]["question_ids"] == ["causal_ate_aipw"]
    pending_task_path = Path(manifest["artifacts"]["runtime_pending_next_task_json"])
    assert pending_task_path.exists()
    pending_task_payload = json.loads(pending_task_path.read_text(encoding="utf-8"))
    assert pending_task_payload["artifact_kind"] == "RuntimePendingNextTask"
    assert pending_task_payload["proof_evidence_status"] == (
        "PENDING_RUNTIME_TASK_NOT_PROOF_EVIDENCE"
    )
    result = json.loads((out_dir / "causal_ate_aipw_runtime_result.json").read_text())
    assert pending_task_payload["source_handoff_id"] == result["traces"][-1][
        "handoff_id"
    ]
    assert pending_task_payload["source_handoff"]["handoff_id"] == (
        pending_task_payload["source_handoff_id"]
    )
    assert pending_task_payload["pending_next_task"]["inputs"][
        "architect_context"
    ]["runtime_resume_source_handoff"]["handoff_id"] == (
        pending_task_payload["source_handoff_id"]
    )
    assert result["traces"][0]["task"]["task_id"] == resume_task["task_id"]
    assert result["traces"][0]["task"]["owner_subsystem"] == "TheoryDeveloper"
    assert (
        result["traces"][0]["task"]["inputs"]["environment_feedback"][
            "failure_classification"
        ]
        == "critic_requested_theory_revision"
    )
    assert (
        result["traces"][0]["task"]["inputs"]["environment_feedback"][
            "required_repair"
        ]
        == "address the exact formal gap before rerouting"
    )
    assert (
        result["traces"][0]["task"]["inputs"]["environment_feedback"][
            "required_revision"
        ]
        == "address the exact formal gap before rerouting"
    )
    assert not result["traces"][0]["task"]["task_id"].startswith("architect:")
    assert manifest["runtime_completion_summary"]["boundary"].startswith(
        "Runtime completion status describes orchestration progress"
    )
    assert (
        manifest["n_runtime_architect_orchestration_feedback_learning_rows"] == 1
    )
    assert (
        manifest["n_runtime_architect_orchestration_feedback_next_action_rows"] == 1
    )
    resume_learning_rows = [
        json.loads(line)
        for line in Path(
            manifest["artifacts"]["runtime_learning_rows_jsonl"]
        ).read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    architect_feedback_rows = [
        row
        for row in resume_learning_rows
        if row.get("learning_task") == "architect_orchestration_feedback"
    ]
    assert len(architect_feedback_rows) == 1
    assert architect_feedback_rows[0]["next_owner_subsystem"] == (
        "ArchitectCoordinator"
    )
    assert architect_feedback_rows[0]["input_summary"]["trigger"] == (
        "RUNTIME_ARCHITECT_CONTEXT_PROPAGATED_WITHOUT_TRACE"
    )
    assert "--resume-through-architect" in architect_feedback_rows[0][
        "recommended_capability_eval_command"
    ]
    resume_agenda_rows = [
        json.loads(line)
        for line in Path(
            manifest["artifacts"]["runtime_next_action_agenda_jsonl"]
        ).read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    architect_agenda_rows = [
        row
        for row in resume_agenda_rows
        if str(row.get("id", "")).startswith("architect:resume_review:")
    ]
    assert len(architect_agenda_rows) == 1
    assert architect_agenda_rows[0]["owner_subsystem"] == "ArchitectCoordinator"
    assert architect_agenda_rows[0]["trigger"] == (
        "RUNTIME_ARCHITECT_CONTEXT_PROPAGATED_WITHOUT_TRACE"
    )

    architect_resume_out_dir = root / "out_architect_resume"
    code = main(
        [
            "research-agent-runtime",
            "--provider",
            "static",
            "--static-response-file",
            str(response_file),
            "--architect-coordinator-provider",
            "static",
            "--architect-static-response-file",
            str(architect_response_file),
            "--simulation-engineer-provider",
            "none",
            "--algorithm-engineer-provider",
            "none",
            "--formalizer-provider",
            "none",
            "--critic-evaluator-provider",
            "none",
            "--question-file",
            "examples/research_questions.json",
            "--resume-runtime-manifest",
            str(resume_manifest),
            "--resume-through-architect",
            "--max-iterations",
            "2",
            "--out",
            str(architect_resume_out_dir),
        ]
    )

    assert code == 0
    architect_manifest = json.loads(
        (architect_resume_out_dir / "research_agent_runtime_manifest.json").read_text()
    )
    assert architect_manifest["runtime_resumed_from_pending_task"] is True
    assert architect_manifest["runtime_resume_policy"] == "architect_resume_review"
    assert architect_manifest["runtime_architect_coordinator_registered"] is True
    assert architect_manifest["runtime_architect_coordinator_executed"] is True
    assert architect_manifest["n_runtime_architect_coordinator_traces"] == 1
    architect_truth_rows = {
        row["evidence_id"]: row
        for row in architect_manifest["runtime_evidence_truth_table"]["rows"]
    }
    assert architect_truth_rows["architect_control"]["status"] == "PRESENT"
    architect_result = json.loads(
        (
            architect_resume_out_dir / "causal_ate_aipw_runtime_result.json"
        ).read_text()
    )
    assert architect_result["traces"][0]["subsystem"] == "ArchitectCoordinator"
    assert architect_result["traces"][0]["task"]["task_id"].startswith(
        "architect-resume:causal_ate_aipw:"
    )
    assert architect_result["traces"][0]["next_task"]["task_id"] == resume_task[
        "task_id"
    ]
    assert architect_result["traces"][1]["subsystem"] == "TheoryDeveloper"
    assert architect_result["traces"][1]["task"]["task_id"] == resume_task["task_id"]
    resume_review = architect_result["traces"][1]["task"]["inputs"][
        "architect_context"
    ]["runtime_resume_review"]
    assert resume_review["pending_task_id"] == resume_task["task_id"]
    assert resume_review["pending_owner_subsystem"] == "TheoryDeveloper"
    architect_audit = audit_research_agent_runtime(
        architect_resume_out_dir,
        architect_resume_out_dir / "runtime_audit",
    )
    architect_scorecard_rows = {
        row["requirement_id"]: row
        for row in architect_audit["capability_scorecard"]["rows"]
    }
    assert architect_scorecard_rows["architect_orchestrated"]["passed"] is True
    assert architect_audit["runtime_architect_coordinator_registered"] is True
    assert architect_audit["runtime_architect_coordinator_executed"] is True
    assert architect_audit["n_runtime_architect_coordinator_traces"] == 1
    assert not any(
        "runtime trace subsystem order is incomplete or misordered" in error
        for row in architect_audit["result_errors"]
        for error in row["errors"]
    )

    learning_file = root / "resume_learning_rows.jsonl"
    learning_file.write_text(
        json.dumps(
            {
                "schema_version": 1,
                "question_id": "causal_ate_aipw",
                "learning_task": "source_to_bridge_premise_derivation_feedback",
                "input_summary": {
                    "failure_classification": (
                        "premise_derivation_candidate_missing_semantic_anchor_reference"
                    ),
                    "premise_name": "hTest",
                },
                "proof_evidence_status": "TEST_LEARNING_ROW_NOT_PROOF_EVIDENCE",
            }
        )
        + "\n",
        encoding="utf-8",
    )
    second_out_dir = root / "out_from_pending_artifact"
    code = main(
        [
            "research-agent-runtime",
            "--provider",
            "static",
            "--static-response-file",
            str(response_file),
            "--architect-coordinator-provider",
            "none",
            "--simulation-engineer-provider",
            "none",
            "--algorithm-engineer-provider",
            "none",
            "--formalizer-provider",
            "none",
            "--critic-evaluator-provider",
            "none",
            "--question-file",
            "examples/research_questions.json",
            "--resume-runtime-manifest",
            str(pending_task_path),
            "--max-iterations",
            "1",
            "--learning-memory-jsonl",
            str(learning_file),
            "--max-learning-memory-rows",
            "1",
            "--out",
            str(second_out_dir),
        ]
    )

    assert code == 0
    second_manifest = json.loads(
        (second_out_dir / "research_agent_runtime_manifest.json").read_text()
    )
    assert (
        second_manifest["runtime_resume_context"][
            "n_rehydrated_blackboard_artifacts"
        ]
        > 0
    )
    assert second_manifest["runtime_resume_policy"] == "direct_pending_task"
    second_result = json.loads(
        (second_out_dir / "causal_ate_aipw_runtime_result.json").read_text()
    )
    assert second_result["traces"][0]["task"]["task_id"] == pending_task_payload[
        "pending_next_task_id"
    ]
    assert second_result["traces"][0]["task"]["task_id"].startswith(
        "simulation:"
    )
    assert second_result["traces"][0]["task"]["inputs"]["architect_context"][
        "runtime_resume_source_handoff"
    ]["handoff_id"] == pending_task_payload["source_handoff_id"]
    resume_memory = second_result["traces"][0]["task"]["inputs"][
        "architect_context"
    ]["runtime_learning_memory"]
    previous_learning_path = out_dir / "runtime_learning_rows.jsonl"
    assert str(previous_learning_path) in resume_memory["source_paths"]
    assert str(learning_file) in resume_memory["source_paths"]
    assert resume_memory["rows"][0]["learning_task"] == (
        "source_to_bridge_premise_derivation_feedback"
    )
    second_blackboard_artifacts = second_result["blackboard"]["artifacts"]
    assert any(
        key.startswith("theory_derivation:")
        for key in second_blackboard_artifacts
    )
    prior_evidence_artifacts = [
        artifact
        for key, artifact in second_blackboard_artifacts.items()
        if key.startswith("runtime_resume_prior_evidence_ledger:")
    ]
    prior_handoff_artifacts = [
        artifact
        for key, artifact in second_blackboard_artifacts.items()
        if key.startswith("runtime_resume_prior_handoff_ledger:")
    ]
    assert len(prior_evidence_artifacts) == 1
    assert len(prior_handoff_artifacts) == 1
    assert prior_evidence_artifacts[0]["artifact_kind"] == (
        "RuntimeResumePriorEvidenceLedger"
    )
    assert prior_handoff_artifacts[0]["artifact_kind"] == (
        "RuntimeResumePriorHandoffLedger"
    )
    assert prior_evidence_artifacts[0]["proof_evidence_status"] == (
        "PRIOR_RUNTIME_LEDGER_NOT_CURRENT_EVIDENCE"
    )
    assert prior_handoff_artifacts[0]["proof_evidence_status"] == (
        "PRIOR_RUNTIME_LEDGER_NOT_CURRENT_EVIDENCE"
    )
    assert prior_evidence_artifacts[0]["n_prior_evidence_rows"] > 0
    assert prior_handoff_artifacts[0]["n_prior_handoff_rows"] > 0
    assert "not as current evidence_ledger or handoff_ledger" in (
        prior_evidence_artifacts[0]["boundary"]
    )
    assert all(
        row["evidence_type"] != "runtime_resume_prior_evidence_ledger"
        for row in second_result["blackboard"]["evidence_ledger"]
    )
    second_audit = audit_research_agent_runtime(
        second_out_dir,
        second_out_dir / "runtime_audit",
    )
    assert second_audit["runtime_resume_prior_ledger_continuity_required"] is True
    assert second_audit["runtime_resume_prior_ledger_continuity_complete"] is True
    assert second_audit["n_runtime_resume_prior_evidence_ledger_artifacts"] == 1
    assert second_audit["n_runtime_resume_prior_handoff_ledger_artifacts"] == 1
    assert second_audit["n_runtime_resume_prior_evidence_ledger_rows"] > 0
    assert second_audit["n_runtime_resume_prior_handoff_ledger_rows"] > 0
    second_scorecard_rows = {
        row["requirement_id"]: row
        for row in second_audit["capability_scorecard"]["rows"]
    }
    assert second_scorecard_rows[
        "runtime_resume_prior_ledger_continuity_complete"
    ]["passed"] is True

    third_out_dir = root / "out_from_pending_artifact_auto_memory"
    code = main(
        [
            "research-agent-runtime",
            "--provider",
            "static",
            "--static-response-file",
            str(response_file),
            "--architect-coordinator-provider",
            "none",
            "--simulation-engineer-provider",
            "none",
            "--algorithm-engineer-provider",
            "none",
            "--formalizer-provider",
            "none",
            "--critic-evaluator-provider",
            "none",
            "--question-file",
            "examples/research_questions.json",
            "--resume-runtime-manifest",
            str(pending_task_path),
            "--max-iterations",
            "1",
            "--out",
            str(third_out_dir),
        ]
    )

    assert code == 0
    third_manifest = json.loads(
        (third_out_dir / "research_agent_runtime_manifest.json").read_text()
    )
    assert (
        third_manifest["runtime_input_context"]["runtime_learning_memory_supplied"]
        is True
    )
    assert third_manifest["runtime_resume_policy"] == "direct_pending_task"
    assert (
        third_manifest["runtime_input_context"]["runtime_learning_memory_rows_loaded"]
        > 0
    )
    third_result = json.loads(
        (third_out_dir / "causal_ate_aipw_runtime_result.json").read_text()
    )
    auto_resume_memory = third_result["traces"][0]["task"]["inputs"][
        "architect_context"
    ]["runtime_learning_memory"]
    assert third_result["traces"][0]["task"]["inputs"]["architect_context"][
        "runtime_resume_source_handoff"
    ]["handoff_id"] == pending_task_payload["source_handoff_id"]
    assert str(previous_learning_path) in auto_resume_memory["source_paths"]
    assert auto_resume_memory["rows"]


def test_research_agent_runtime_cli_imports_truth_table_memory_into_semantic_queue() -> None:
    root = Path("runs/test_research_agent_runtime_truth_table_memory_cli")
    shutil.rmtree(root, ignore_errors=True)
    root.mkdir(parents=True, exist_ok=True)
    response_file = root / "response.json"
    learning_file = root / "truth_table_runtime_learning_rows.jsonl"
    out_dir = root / "out"
    response_file.write_text(json.dumps(_runtime_sample_response()), encoding="utf-8")
    learning_file.write_text(
        json.dumps(
            {
                "schema_version": 1,
                "artifact_kind": "RuntimeLearningRow",
                "question_id": "conformal_prediction_coverage",
                "learning_task": "source_theorem_truth_table_feedback",
                "target_theorem_name": "split_conformal_coverage",
                "work_order_id": "truth_table_feedback:hGoodCovered",
                "premise_name": "hGoodCovered",
                "premise_target_type": "{ω | rank ω ∈ GoodRanks} ⊆ covered",
                "premise_derivation_gap_kind": (
                    "proof_body_verified_adapter_context_insufficient"
                ),
                "recommended_next_action": (
                    "derive hGoodCovered from exact source hypotheses before "
                    "rerunning the exact source theorem proof body"
                ),
                "input_summary": {
                    "trigger": "RUNTIME_EVIDENCE_TRUTH_TABLE",
                    "target_theorem_name": "split_conformal_coverage",
                    "source_theorem_kernel_verified": False,
                    "proof_body_goal_reached": True,
                    "failure_classification": (
                        "proof_body_verified_adapter_context_insufficient"
                    ),
                    "premise_name": "hGoodCovered",
                    "premise_target_type": "{ω | rank ω ∈ GoodRanks} ⊆ covered",
                    "premise_derivation_gap_kind": (
                        "proof_body_verified_adapter_context_insufficient"
                    ),
                    "proof_body_goal_excerpt": [
                        "hGoodCovered : {ω | rank ω ∈ GoodRanks} ⊆ covered",
                        "⊢ P {ω | s (Fin.last m) ω ≤ q_hat ω} ≥ ENNReal.ofReal (1 - alpha)",
                    ],
                },
                "proof_evidence_status": (
                    "RUNTIME_TRUTH_TABLE_FEEDBACK_NOT_PROOF_EVIDENCE"
                ),
            }
        )
        + "\n",
        encoding="utf-8",
    )

    code = main(
        [
            "research-agent-runtime",
            "--provider",
            "static",
            "--static-response-file",
            str(response_file),
            "--architect-coordinator-provider",
            "none",
            "--simulation-engineer-provider",
            "none",
            "--algorithm-engineer-provider",
            "none",
            "--formalizer-provider",
            "none",
            "--critic-evaluator-provider",
            "none",
            "--question-file",
            "examples/research_questions.json",
            "--question-id",
            "conformal_prediction_coverage",
            "--max-questions",
            "1",
            "--runs",
            "80",
            "--learning-memory-jsonl",
            str(learning_file),
            "--max-learning-memory-rows",
            "5",
            "--out",
            str(out_dir),
        ]
    )

    assert code == 0
    manifest = json.loads((out_dir / "research_agent_runtime_manifest.json").read_text())
    assert manifest["question_ids"] == ["conformal_prediction_coverage"]
    assert (
        manifest[
            "n_runtime_source_theorem_semantic_primitive_work_orders_from_input_learning_memory"
        ]
        >= 1
    )
    queue_path = Path(
        manifest["artifacts"][
            "runtime_source_theorem_semantic_primitive_work_orders_from_source_to_bridge_premise_derivation_jsonl"
        ]
    )
    assert queue_path.exists()
    queue_rows = [
        json.loads(line)
        for line in queue_path.read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    assert any(
        row.get("premise_name") == "hGoodCovered"
        and row.get("premise_target_type") == "{ω | rank ω ∈ GoodRanks} ⊆ covered"
        and row.get("runtime_queue_status")
        == "PENDING_SOURCE_TO_BRIDGE_PREMISE_SEMANTIC_REPAIR"
        and row.get("proof_evidence_status") == "WORK_ORDER_NOT_PROOF_EVIDENCE"
        for row in queue_rows
    )
